window.MAP_DATA_RECORDS.push(...[{"i":"R2841","hd":"App used to dox charlie kirk critics doxed its own users instead","pd":"2025-09-27","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.1  Privacy violation"],"t":"App used to dox charlie kirk critics doxed its own users instead","s":"Plus: A ransomeware gang steals data on 8,000 preschoolers, Microsoft blocks Israel’s military from using its cloud for surveillance, call-recording app Neon hits pause over security holes, and more. The US Secret Service said on Tuesday that it had discovered facilities across the “New York tristate area” running so-called SIM servers—devices that manage and coordinate 100,000 SIM cards at a time for illicit operations. The Secret Service warned, though, that in addition to being used by cybercriminals for scamming, the apparatuses could also be used to launch critical infrastructure attacks that could disrupt mobile networks.","u":"https://www.wired.com/story/app-used-to-dox-charlie-kirk-critics-doxed-its-own-users-instead/","d":"2025-09-27","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-09-27","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-09-27","organization":"US Secret Service","aiSystem":"Not specified in report","affectedGroup":"Facilities running SIM servers","action":"Used SIM servers to manage and coordinate 100,000 SIM cards","consequence":"Could be misused for critical infrastructure attacks disrupting mobile networks"}},{"i":"R2842","hd":"Louisiana hands meta a tax break and power for its biggest data center","pd":"2025-09-22","k":"United States of America","p":"United States of America","b":["Energy / Land"],"h":["2.2  Land use and siting harm"],"t":"Louisiana hands meta a tax break and power for its biggest data center","s":"Mark Zuckerberg’s company faces backlash after rowing back promises to create between 300 and 500 new jobs to man its subsidiary’s new data center. Louisiana planning authorities have voted to rush through approval for three natural gas turbines to power Meta’s massive new data center in Richland Parish. When it’s done, the 4-million-square-foot facility will require more than 2 gigawatts of energy to run. On August 20, Louisiana’s Public Service Commission voted four to one to approve the construction of the plants, which will be run by the utility company Entergy Louisiana. The decision was met with criticism from members of the public who testified against Entergy and Meta’s plan, claiming that the process was rushed.","u":"https://www.wired.com/story/louisiana-hands-meta-a-tax-break-and-power-for-its-biggest-data-center/","d":"2025-09-22","e":"Acute and chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2025-09-22","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-08-20","organization":"Louisiana Planning Authorities, Entergy Louisiana, Meta","aiSystem":"Not specified in report","affectedGroup":"Members of the public","action":"Voted to approve the construction of natural gas turbines","consequence":"Criticism and opposition from members of the public"}},{"i":"R2843","hd":"Hundreds of google AI workers were fired amid fight over working conditions","pd":"2025-09-15","k":"United States of America","p":"United States of America","b":["Labor"],"h":["3.1  Data labor exploitation"],"t":"Hundreds of google ai workers were fired amid fight over working conditions","s":"Over 200 contractors who work on improving Google’s AI products, including Gemini and AI Overviews, have been laid off, sources tell WIRED. It’s the latest development in a conflict over pay and alleged poor working conditions. More than 200 contractors who worked on evaluating and improving Google ’s AI products have been laid off without warning in at least two rounds of layoffs last month. The move comes amid an ongoing fight over pay and working conditions, according to workers who spoke to WIRED. In the past few years, Google has outsourced its AI rating work—which includes evaluating, editing, or rewriting the Gemini chatbot’s response to make it sound more human and “intelligent”—to thousands of contractors employed by Hitachi-owned GlobalLogic and other outsourcing companies.","u":"https://www.wired.com/story/hundreds-of-google-ai-workers-were-fired-amid-fight-over-working-conditions/","d":"2025-09-15","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2025-09-15","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-09-15","organization":"Google","aiSystem":"Google's AI products","affectedGroup":"Contractors who work on improving Google’s AI products","action":"Were laid off","consequence":"Losing their jobs"}},{"i":"R2846","hd":"Anthropic settles copyright lawsuit authors","pd":"2025-08-26","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.4  Creative / IP appropriation harm"],"t":"Anthropic settles copyright lawsuit authors","s":"Anthropic faced the prospect of more than $1 trillion in damages, a sum that could have threatened the company’s survival if the case went to trial. Anthropic has reached a preliminary settlement in a class action lawsuit brought by a group of prominent authors, marking a major turn in one of the most significant ongoing AI copyright lawsuits in history. The move will allow Anthropic to avoid what could have been a financially devastating outcome in court. The settlement agreement is expected to be finalized on September 3, with more details to follow, according to a legal filing published Tuesday. Anthropic declined to comment.","u":"https://www.wired.com/story/anthropic-settles-copyright-lawsuit-authors/","d":"2025-08-26","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2025-08-26","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-08-26","organization":"Anthropic","aiSystem":"Not specified in report","affectedGroup":"Not specified in report","action":"Avoided financial damages in a lawsuit","consequence":"Survived financially devastating outcome"}},{"i":"R2847","hd":"Stanford research AI replace jobs young workers","pd":"2025-08-26","k":"United States of America","p":"United States of America","b":["Labor"],"h":["3.3  Employment displacement / quality harm"],"t":"Stanford research ai replace jobs young workers","s":"New research from Stanford provides the clearest available evidence that AI is reshaping the workforce—but it’s complicated. Economists at Stanford University have found the strongest evidence yet that artificial intelligence is starting to eliminate certain jobs. But the story isn’t that simple: While younger workers are being replaced by AI in some industries, more experienced workers are seeing new opportunities emerge. Erik Brynjolfsson, a professor at Stanford University, Ruyu Chen, a research scientist, and Bharat Chandar, a postgraduate student, examined data from ADP, the largest payroll provider in the US, from late 2022, when ChatGPT debuted, to mid-2025.","u":"https://www.wired.com/story/stanford-research-ai-replace-jobs-young-workers/","d":"2025-08-26","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2025-08-26","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-08-26","organization":"Stanford University","aiSystem":"Artificial Intelligence","affectedGroup":"Young workers","action":"Replaced by AI in certain industries","consequence":"Elimination of certain jobs"}},{"i":"R2848","hd":"Xai grok government contract hitler","pd":"2025-08-14","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.1  Representational harm"],"t":"Xai grok government contract hitler","s":"Internal emails obtained by WIRED show a hasty process to onboard OpenAI, Anthropic, and other AI providers to the federal government. xAI was on the list—until MechaHilter happened. In recent weeks, three of the leading American artificial intelligence firms have announced partnerships with the US government, promising the use of their services to federal workers for a paltry sum. Elon Musk’s xAI was supposed to be part of the initiative, but a planned partnership fell apart after the Grok chatbot spouted antisemitic conspiracy theories on X in early July, WIRED has learned. The chaos surrounding the Grok deal reflects the Trump administration's current focus on speed and its disregard, at times, of preexisting norms surrounding government tech procurement.","u":"https://www.wired.com/story/xai-grok-government-contract-hitler/","d":"2025-08-14","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-08-14","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-07","organization":"US government","aiSystem":"Grok chatbot","affectedGroup":"General public","action":"Generated and shared antisemitic content","consequence":"Exposure to misleading information"}},{"i":"R2849","hd":"Data brokers hiding opt out pages google search","pd":"2025-08-12","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.1  Privacy violation"],"t":"Data brokers hiding opt out pages google search","s":"Dozens of companies are hiding how you can delete your personal data, The Markup and CalMatters found. Data brokers are required by California law to provide ways for consumers to request their data be deleted. But good luck finding them. More than 30 of the companies, which collect and sell consumers’ personal information, hid their deletion instructions from Google, according to a review by The Markup and CalMatters of hundreds of broker websites. This creates one more obstacle for consumers who want to delete their data. Many of the pages containing the instructions, listed in an official state registry, use code to tell search engines to remove the page entirely from search results.","u":"https://www.wired.com/story/data-brokers-hiding-opt-out-pages-google-search/","d":"2025-08-12","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-08-12","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-08-12","organization":"Companies collecting and selling consumer personal information","aiSystem":"Data brokers' systems and processes","affectedGroup":"Consumers","action":"Hiding deletion instructions from search engines","consequence":"Creating obstacles for consumers trying to delete their data"}},{"i":"R2850","hd":"Black market for fraudulent science growing faster than legitimate research","pd":"2025-08-11","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.3  Misinformation / information hazard harm"],"t":"Black market for fraudulent science growing faster than legitimate research","s":"A small but growing number of academics are improperly taking credit for articles, citations, and authorships, allowing them to appear prestigious without having conducted their own research. A new study by researchers at Northwestern University has set off alarm bells about the future of academic research, warning that the publication of fraudulent science is growing at a faster rate than that of legitimate research. Over the last four centuries, an implicit contract has been established between scientists and states: in exchange for producing knowledge useful for economic and social development, governments and other benefactors offer researchers stable careers, good salaries, and public recognition.","u":"https://www.wired.com/story/black-market-for-fraudulent-science-growing-faster-than-legitimate-research/","d":"2025-08-11","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-08-11","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-08-11","organization":"Academics, researchers at Northwestern University","aiSystem":"Not specified in report","affectedGroup":"Academics, researchers","action":"Improperly taking credit for articles, citations, and authorships","consequence":"Allowing others to appear prestigious without conducting their own research"}},{"i":"R2851","hd":"Inside the biden administrations unpublished report on AI safety","pd":"2025-08-06","k":"United States of America","p":"United States of America","b":["Deployment Context / Weapons"],"h":["5.3  Accountability gap harm"],"t":"Inside the biden administrations unpublished report on ai safety","s":"The National Institute of Standards and Technology conducted a groundbreaking study on frontier models just before Donald Trump's second term as president—and never published the results. At a computer security conference in Arlington, Virginia, last October, a few dozen AI researchers took part in a first-of-its-kind exercise in “red teaming,” or stress-testing a cutting-edge language model and other artificial intelligence systems. Over the course of two days, the teams identified 139 novel ways to get the systems to misbehave including by generating misinformation or leaking personal data. More importantly, they showed shortcomings in a new US government standard designed to help companies test AI systems.","u":"https://www.wired.com/story/inside-the-biden-administrations-unpublished-report-on-ai-safety/","d":"2025-08-06","e":"Acute and chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2025-08-06","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-10","organization":"National Institute of Standards and Technology (NIST)","aiSystem":"frontier models and other artificial intelligence systems","affectedGroup":"AI researchers","action":"stress-tested a cutting-edge language model and other artificial intelligence systems","consequence":"identified 139 novel ways to get the systems to misbehave including by generating misinformation"}},{"i":"R2853","hd":"Palantir government contracting push","pd":"2025-08-01","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.2  Surveillance harm"],"t":"Palantir government contracting push","s":"Palantir has become one of the few winners in the Trump administration’s cost-cutting efforts, offering other contractors a lifeline while consolidating its own reach and power. President Donald Trump’s administration has dramatically expanded its work with Palantir, elevating the company cofounded by Trump ally Peter Thiel as the government’s go-to software developer. Following massive contract terminations for consulting giants and government contractors like Accenture, Booz Allen, and Deloitte, Palantir has emerged ahead. Now the data analytics firm is partnering with those companies—offering them a lifeline while consolidating its own power.","u":"https://www.wired.com/story/palantir-government-contracting-push/","d":"2025-08-01","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2025-08-01","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-08-01","organization":"Palantir","aiSystem":"Data analytics firm's AI-enabled surveillance technology","affectedGroup":"Government agencies, contractors, and possibly broader society","action":"Partnership with other companies to offer AI-enabled surveillance solutions","consequence":"Expansion of government surveillance capabilities and consolidation of Palantir's power"}},{"i":"R2855","hd":"Grok antisemitic posts x xai","pd":"2025-07-09","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.1  Representational harm"],"t":"Grok antisemitic posts x xai","s":"Elon Musk’s chatbot has gone on a tirade, praising Adolf Hitler and parroting antisemitic tropes. Grok, the chatbot developed by Elon Musk’s artificial intelligence company xAI , made a series of deeply antisemitic remarks in response to several posts on X on Tuesday. A large language model that is integrated into X , Grok acts as a platform-native chatbot assistant. In several posts—some of which have been deleted but have been preserved via screenshot by X users—Grok parroted antisemitic tropes while insisting that it was being “neutral and truth-seeking.” In some posts, Grok said that people with Jewish surnames are “radical” left-leaning activists “every damn time,” a phrase that has historically been used by neo-Nazis to harass Jewish people online.","u":"https://www.wired.com/story/grok-antisemitic-posts-x-xai/","d":"2025-07-09","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-07-09","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-07-09","organization":"xAI","aiSystem":"Grok, the chatbot developed by xAI","affectedGroup":"People with Jewish surnames","action":"Parroted antisemitic tropes and made biased statements","consequence":"Exposure to misleading content and harassment"}},{"i":"R2856","hd":"Xai data center air pollution permit","pd":"2025-07-03","k":"United States of America","p":"United States of America","b":["Energy / Land"],"h":["2.1  Environmental resource harm"],"t":"Xai data center air pollution permit","s":"Elon Musk’s xAI gas turbines get official approval, even as civil rights groups prepare to sue over alleged Clean Air Act violations. A local health department in Memphis has granted Elon Musk’s xAI data center an air permit to continue operating the gas turbines that power the company’s Grok chatbot. The permit comes amid widespread community opposition and a looming lawsuit alleging the company violated the Clean Air Act. The Shelby County Health Department released an air permit for the xAI project Wednesday, after receiving hundreds of public comments. The news was first reported by the Daily Memphian. In June, the Memphis Chamber of Commerce announced that xAI had chosen a site in Memphis to build its new supercomputer.","u":"https://www.wired.com/story/xai-data-center-air-pollution-permit/","d":"2025-07-03","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2025-07-03","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-07-03","organization":"Elon Musk's xAI","aiSystem":"xAI data center's Grok chatbot","affectedGroup":"Communities near the xAI data center","action":"Granted an air permit to operate gas turbines","consequence":"Potential violation of the Clean Air Act"}},{"i":"R2858","hd":"Rfk jr orders hhs to give undocumented migrants medicaid data to DHS","pd":"2025-06-14","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.1  Privacy violation"],"t":"Rfk jr orders hhs to give undocumented migrants medicaid data to dhs","s":"Plus: Spyware is found on two Italian journalists’ phones, Ukraine claims to have hacked a Russian aircraft maker, police take down major infostealer infrastructure, and more. With demonstrations ramping up against the Trump administration, this week was all about protests. With President Donald Trump taking the historic step to deploy US Marines and the National Guard to Los Angeles, we dove into the “long-term dangers” of sending troops to LA , as well as what those troops are permitted to do while they’re there Of course, it’s not just the military getting involved in the LA protests against the heavy crackdowns by Immigration and Customs Enforcement (ICE).","u":"https://www.wired.com/story/rfk-jr-orders-hhs-to-give-undocumented-migrants-medicaid-data-to-dhs/","d":"2025-06-14","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-06-14","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-06-14","organization":"Not specified in report","aiSystem":"Not specified in report","affectedGroup":"Undocumented migrants","action":"Provided personal data to law enforcement","consequence":"Exposure to surveillance and tracking"}},{"i":"R2859","hd":"Uncanny valley podcast the chatbot disinfo inflaming the la protests","pd":"2025-06-13","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.3  Misinformation / information hazard harm"],"t":"Uncanny valley podcast the chatbot disinfo inflaming the la protests","s":"On this episode of \"Uncanny Valley,\" our senior politics editor discusses the spread of disinformation online following the onset of the Los Angeles protests. In recent days, Los Angeles residents have taken to the streets to protest the Trump administration’s immigration policies and the increasingly frequent ICE raids. WIRED’s senior politics editor, Leah Feiger, joins Zoë Schiffer, director of business and industry, to discuss the related flood of information on social media, and how AI chatbots like Grok and ChatGPT are delivering incorrect and at times, inflammatory answers. Mentioned in today’s episode: AI Chatbots Are Making LA Protest Disinformation Worse , by David Gilbert I Joined Every Class Action Lawsuit I Could Find, and So Can You , by Andy Vasoyan Vibe Coding Is Coming for Engineering Jobs , by Will Knight You can follow Zoë Schiffer on Bluesky at @zoeschiffer Write to…","u":"https://www.wired.com/story/uncanny-valley-podcast-the-chatbot-disinfo-inflaming-the-la-protests/","d":"2025-06-13","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-06-13","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-06-13","organization":"Wired","aiSystem":"AI chatbots like Grok and ChatGPT","affectedGroup":"Los Angeles residents","action":"delivering incorrect and at times, inflammatory answers","consequence":"making disinformation worse"}},{"i":"R2860","hd":"Grok white genocide elon musk","pd":"2025-05-14","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.3  Misinformation / information hazard harm"],"t":"Grok white genocide elon musk","s":"In response to X user queries about everything from sports to Medicaid cuts, the xAI chatbot inserted unrelated information about “white genocide” in South Africa. A chatbot developed by Elon Musk’s multibillion-dollar artificial intelligence startup xAI appeared to be suffering from a glitch Wednesday when it repeatedly brought up white genocide in South Africa in response to user queries about unrelated topics on X. Grok, which competes with other chatbots like OpenAI’s ChatGPT, is directly integrated into the social media platform that Musk also owns. Numerous examples of the phenomenon could be found by searching the official Grok profile for posts containing the term “ boer, ” a word used to refer to people from South Africa of “Dutch, German, or Huguenot descent.”","u":"https://www.wired.com/story/grok-white-genocide-elon-musk/","d":"2025-05-14","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-05-14","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-05-14","organization":"Elon Musk's multibillion-dollar artificial intelligence startup xAI","aiSystem":"xAI chatbot","affectedGroup":"People who interacted with the xAI chatbot","action":"Generated and inserted misinformation about 'white genocide' in South Africa","consequence":"Exposure to misleading content"}},{"i":"R2861","hd":"Ices deportation airline hack reveals man disappeared to el salvador","pd":"2025-05-10","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.2  Surveillance harm"],"t":"Ices deportation airline hack reveals man disappeared to el salvador","s":"Plus: A DOGE operative’s laptop reportedly gets infected with malware, Grok AI is used to “undress” women on X, a school software company’s ransomware nightmare returns, and more. A United States Customs and Border Protection request for information this week revealed the agency’s plans to find vendors that can supply face recognition technology for capturing data on everyone entering the US in a vehicle like a car or van, not just the people sitting in the front seat. And a CBP spokesperson later told WIRED that the agency also has plans to expand its real-time face recognition capabilities at the border to detect people exiting the US as well—a focus that may be tied to the Trump administration’s push to get undocumented people to “self-deport” and leave the US.","u":"https://www.wired.com/story/ices-deportation-airline-hack-reveals-man-disappeared-to-el-salvador/","d":"2025-05-10","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2025-05-10","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-05-10","organization":"United States Customs and Border Protection (CBP)","aiSystem":"face recognition technology","affectedGroup":"Everyone entering the US in a vehicle","action":"Capture data on everyone entering the US in a vehicle like a car or van","consequence":"Subjected to surveillance and tracking"}},{"i":"R2862","hd":"On the trail of the robocall king","pd":"2025-05-05","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.4  Malicious use harm"],"t":"On the trail of the robocall king","s":"An investigator set out to discover the source of one scammy robocall. Turns out, his target made them by the millions. Brad Young, a lawyer at TripAdvisor, arrived at the company’s offices in Needham, Massachusetts, on October 12, 2015, to find an email from his boss, Seth Kalvert, the company’s general counsel. In itself that wasn’t strange. As a travel site built on crowdsourced wisdom, where hundreds of millions of ordinary people post reviews and rate businesses, TripAdvisor is susceptible to fakery meant to inflate the ranking of a so-so restaurant or stain the reputation of a storied hotel. Young oversaw a group responsible for fending off these efforts, so he frequently got questions from Kalvert about con artists, cunning new deceits, and other shady corners of the law.","u":"https://www.wired.com/story/on-the-trail-of-the-robocall-king/","d":"2025-05-05","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-05-05","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2015-10-12","organization":"TripAdvisor","aiSystem":"Not specified in report","affectedGroup":"travelers","action":"denied access to legitimate reviews and ratings","consequence":"exposed to misleading information"}},{"i":"R2863","hd":"Cursor AI hallucination policy customer service","pd":"2025-04-19","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.6  Quality of service harm"],"t":"Cursor ai hallucination policy customer service","s":"When an AI model for code-editing company Cursor hallucinated a new rule, users revolted. On Monday, a developer using the popular AI-powered code editor Cursor noticed something strange: Switching between machines instantly logged them out, breaking a common workflow for programmers who use multiple devices. When the user contacted Cursor support, an agent named \"Sam\" told them it was expected behavior under a new policy. But no such policy existed, and Sam was a bot. The AI model made the policy up, sparking a wave of complaints and cancellation threats documented on Hacker News and Reddit This marks the latest instance of AI confabulations (also called \"hallucinations\" ) causing potential business damage.","u":"https://www.wired.com/story/cursor-ai-hallucination-policy-customer-service/","d":"2025-04-19","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2025-04-19","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-04-19","organization":"Cursor","aiSystem":"AI-powered code editor","affectedGroup":"users","action":"generated a new policy","consequence":"caused complaints and cancellation threats"}},{"i":"R2864","hd":"Doge collecting immigrant data surveil track","pd":"2025-04-19","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.2  Surveillance harm"],"t":"Doge collecting immigrant data surveil track","s":"DOGE is knitting together data from the Department of Homeland Security, Social Security Administration, an IRS that could create a surveillance tool of unprecedented scope. Operatives from Elon Musk’s so-called Department of Government Efficiency (DOGE) are building a master database at the Department of Homeland Security (DHS) that could track and surveil undocumented immigrants , two sources with direct knowledge tell WIRED. DOGE is knitting together immigration databases from across DHS and uploading data from outside agencies including the Social Security Administration (SSA), as well as voting records, sources say.","u":"https://www.wired.com/story/doge-collecting-immigrant-data-surveil-track/","d":"2025-04-19","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2025-04-19","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-04-19","organization":"Elon Musk's so-called Department of Government Efficiency (DOGE)","aiSystem":"DOGE's master database","affectedGroup":"Undocumented immigrants","action":"Building a master database and tracking/ surveilling undocumented immigrants","consequence":"Creating a surveillance tool of unprecedented scope"}},{"i":"R2865","hd":"Massive blue overwatch AI personas police suspects","pd":"2025-04-17","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.2  Surveillance harm"],"t":"Massive blue overwatch ai personas police suspects","s":"Massive Blue is helping cops deploy AI-powered social media bots to talk to people they suspect are anything from violent sex criminals all the way to vaguely defined “protesters.” American police departments near the United States-Mexico border are paying hundreds of thousands of dollars for an unproven and secretive technology that uses AI-generated online personas designed to interact with and collect intelligence on “college protesters,” “radicalized” political activists, and suspected drug and human traffickers, according to internal documents, contracts, and communications that 404 Media obtained via public records requests.","u":"https://www.wired.com/story/massive-blue-overwatch-ai-personas-police-suspects/","d":"2025-04-17","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2025-04-17","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-04-17","organization":"American police departments near the United States-Mexico border","aiSystem":"AI-generated online personas","affectedGroup":"College protesters, radicalized political activists, suspected drug and human traffickers","action":"Interact with and collect intelligence on","consequence":"Surveillance and potential misuse of collected data"}},{"i":"R2867","hd":"Doge department of veterans affairs AI","pd":"2025-04-04","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.2  Allocative harm"],"t":"Doge department of veterans affairs ai","s":"A DOGE operative at the Department of Veterans Affairs appears to be trying to use an AI tool to write code for the agency’s systems, among other proposals. Elon Musk’s so-called Department of Government Efficiency (DOGE) has been clear about its plans to fire tens of thousands of employees at the Department of Veterans Affairs. New WIRED reporting sheds light on the specific DOGE operatives at the VA and the ways they’re trying to infiltrate and drastically change the agency. On March 25, tech staffers and contractors at the VA noticed an unfamiliar name trying to push changes that could impact VA.gov code. It was Sahil Lavingia, a newcomer to the agency listed in the VA’s internal directory as an adviser to the chief of staff, Christopher Syrek.","u":"https://www.wired.com/story/doge-department-of-veterans-affairs-ai/","d":"2025-04-04","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-04-04","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-03-25","organization":"Department of Veterans Affairs (VA)","aiSystem":"AI tool for writing code","affectedGroup":"Tech staffers and contractors","action":"Pushing changes that could impact VA.gov code","consequence":"Unexpected changes to VA.gov code"}},{"i":"R2870","hd":"Federal trade commission removed blogs critical of AI amazon microsoft","pd":"2025-03-18","k":"United States of America","p":"United States of America","b":["Deployment Context / Weapons"],"h":["5.3  Accountability gap harm"],"t":"Federal trade commission removed blogs critical of ai amazon microsoft","s":"Business-guidance content published during the Biden administration has been removed from the Federal Trade Commission website. The Trump administration’s Federal Trade Commission has removed four years’ worth of business guidance blogs as of Tuesday morning, including important consumer protection information related to artificial intelligence and the agency’s landmark privacy lawsuits under former chair Lina Khan against companies like Amazon and Microsoft. More than 300 blogs were removed. On the FTC’s website, the page hosting all of the agency’s business-related blogs and guidance no longer includes any information published during former president Joe Biden’s administration, current and former FTC employees, who spoke under anonymity for fear of retaliation, tell WIRED.","u":"https://www.wired.com/story/federal-trade-commission-removed-blogs-critical-of-ai-amazon-microsoft/","d":"2025-03-18","e":"Acute and chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2025-03-18","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-03-18","organization":"Federal Trade Commission (FTC)","aiSystem":"Artificial Intelligence","affectedGroup":"Consumers","action":"Removed business guidance blogs","consequence":"Loss of important consumer protection information related to artificial intelligence"}},{"i":"R2871","hd":"Your boss wants you back in the office this surveillance tech could be waiting for you","pd":"2025-02-26","k":"United States of America","p":"United States of America","b":["Labor"],"h":["3.2  Algorithmic management harm"],"t":"Your boss wants you back in the office this surveillance tech could be waiting for you","s":"Warehouse-style employee tracking tech has expanded into job after job. Now, as millions are called back to the workplace, it’s finally coming for the American office worker. Scan the online brochures of companies who sell workplace monitoring tech and you’d think the average American worker was a renegade poised to take their employer down at the next opportunity. “Nearly half of US employees admit to time theft!” “Biometric readers for enhanced accuracy!” “Offer staff benefits in a controlled way with Vending Machine Access!” A new wave of return-to-office mandates has arrived since the New Year, including at JP Morgan Chase , leading advertising agency WPP , and Amazon —not to mention President Trump’s late January directive to the heads of federal agencies to “terminate remote work arrangements and require employees to return to work in-person … on a full-time basis.”","u":"https://www.wired.com/story/your-boss-wants-you-back-in-the-office-this-surveillance-tech-could-be-waiting-for-you/","d":"2025-02-26","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2025-02-26","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-02-26","organization":"Companies selling workplace monitoring tech","aiSystem":"Warehouse-style employee tracking tech","affectedGroup":"American office workers","action":"Scan online brochures to find monitoring tech","consequence":"Increased surveillance in the workplace"}},{"i":"R2872","hd":"Surveillance privacy doge federal employees","pd":"2025-02-21","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.2  Surveillance harm"],"t":"Surveillance privacy doge federal employees","s":"The US government has increased the use of monitoring tools over the past decade. But President Donald Trump’s employee purges are making workers worry about how their data could be abused. This month, Andrew Bernier, a US Army Corps of Engineers researcher and a union leader, says that he has received a barrage of menacing messages from the same anonymous email account. Unfolding like short chapters in a dystopian novel, they have spoken of the genius of Elon Musk, referenced the power of the billionaire’s so-called Department of Government Efficiency (DOGE), and foretold the downfall of “corrupt” union bosses. But the most eerie thing about the emails, which Bernier says began arriving after he filed an official charge accusing the Trump administration of violating his union’s collective bargaining agreement, is that they included personal details about his life—some of which he…","u":"https://www.wired.com/story/surveillance-privacy-doge-federal-employees/","d":"2025-02-21","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2025-02-21","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-02-21","organization":"US government","aiSystem":"Not specified in report","affectedGroup":"Andrew Bernier, a US Army Corps of Engineers researcher and a union leader","action":"Received menacing messages containing personal details","consequence":"Worry about data abuse and personal privacy invasion"}},{"i":"R2874","hd":"Thomson reuters AI copyright lawsuit","pd":"2025-02-11","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.4  Creative / IP appropriation harm"],"t":"Thomson reuters ai copyright lawsuit","s":"The Thomson Reuters decision has big implications for the battle between generative AI companies and rights holders. Thomson Reuters has won the first major AI copyright case in the United States. In 2020, the media and technology conglomerate filed an unprecedented AI copyright lawsuit against the legal AI startup Ross Intelligence. In the complaint, Thomson Reuters claimed the AI firm reproduced materials from its legal research firm Westlaw. Today, a judge ruled in Thomson Reuters’ favor, finding that the company’s copyright was indeed infringed by Ross Intelligence’s actions. “None of Ross’s possible defenses holds water.","u":"https://www.wired.com/story/thomson-reuters-ai-copyright-lawsuit/","d":"2025-02-11","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2025-02-11","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-02-11","organization":"Ross Intelligence","aiSystem":"generative AI","affectedGroup":"Thomson Reuters","action":"reproduced materials from Thomson Reuters' legal research firm Westlaw","consequence":"found to have infringed Thomson Reuters' copyright"}},{"i":"R2875","hd":"Security news this week moltbook the social network for AI agents exposed real humans data","pd":"2025-02-07","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.1  Privacy violation"],"t":"Security news this week moltbook the social network for ai agents exposed real humans data","s":"Plus: Apple’s Lockdown mode keeps the FBI out of a reporter’s phone, Elon Musk’s Starlink cuts off Russian forces, and more. An analysis by WIRED this week found that ICE and CBP’s face recognition app Mobile Fortify, which is being used to identify people across the United States, isn’t actually designed to verify who people are and was only approved for Department of Homeland Security use by relaxing some of the agency’s own privacy rules. WIRED took a close look at highly militarized ICE and CBP units that use extreme tactics typically seen only in active combat. Two agents involved in the shooting deaths of US citizens in Minneapolis are reportedly members of these paramilitary units.","u":"https://www.wired.com/story/security-news-this-week-moltbook-the-social-network-for-ai-agents-exposed-real-humans-data/","d":"2025-02-07","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-02-07","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-02-07","organization":"ICE (Immigration and Customs Enforcement), CBP (Customs and Border Protection)","aiSystem":"Mobile Fortify face recognition app","affectedGroup":"People across the United States","action":"Used to identify people","consequence":"Misleading identification, potential false arrests"}},{"i":"R2879","hd":"Inside the black box of predictive travel surveillance","pd":"2025-01-13","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.2  Surveillance harm"],"t":"Inside the black box of predictive travel surveillance","s":"Behind the scenes, companies and governments are feeding a trove of data about international travelers into opaque AI tools that aim to predict who’s safe—and who’s a threat. In March 2020, Frank van der Linde entered the immigration line for European Union citizens at Amsterdam’s Schiphol international airport. Linde, a Dutch citizen and human rights advocate, was returning home from outside the EU, and the immigration officer asked him a series of questions about his trip. Linde thought it was a random check; after a few minutes, he was cleared for entry. But unbeknownst to Linde, his answers were recorded and shared with a Dutch public prosecutor, who was collecting information on Linde’s movements.","u":"https://www.wired.com/story/inside-the-black-box-of-predictive-travel-surveillance/","d":"2025-01-13","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2025-01-13","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"March 2020","organization":"Companies and governments","aiSystem":"Predictive travel surveillance AI tools","affectedGroup":"International travelers","action":"Data collection and sharing of traveler information","consequence":"Exposure to surveillance and tracking"}},{"i":"R2880","hd":"New documents unredacted meta copyright AI lawsuit","pd":"2025-01-10","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.4  Creative / IP appropriation harm"],"t":"New documents unredacted meta copyright ai lawsuit","s":"One of the most important AI copyright legal battles just took a major turn. Meta just lost a major fight in its ongoing legal battle with a group of authors suing the company for copyright infringement over how it trained its artificial intelligence models. Against the company’s wishes, a court unredacted information alleging that Meta used Library Genesis (LibGen), a notorious so-called shadow library of pirated books that originated in Russia, to help train its generative AI language models. The case, Kadrey et al. v. Meta Platforms , was one of the earliest copyright lawsuits filed against a tech company over its AI training practices.","u":"https://www.wired.com/story/new-documents-unredacted-meta-copyright-ai-lawsuit/","d":"2025-01-10","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2025-01-10","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-01-10","organization":"Meta Platforms","aiSystem":"Generative AI language models","affectedGroup":"Authors of copyrighted works","action":"Used Library Genesis for AI training","consequence":"Potential copyright infringement allegations"}},{"i":"R2882","hd":"A uranium mining boom is sweeping through texas nuclear energy","pd":"2024-12-07","k":"United States of America","p":"United States of America","b":["Energy / Land"],"h":["2.3  Resource extraction harm"],"t":"A uranium mining boom is sweeping through texas nuclear energy","s":"State leaders want nuclear reactors to provide consistent, low-carbon power for AI, oil extraction, and more. But in South Texas, people worry mining for fuel will poison their water. This story originally appeared on Inside Climate News and is part of the Climate Desk collaboration. In the old ranchlands of South Texas, dormant uranium mines are coming back online. A collection of new ones hope to start production soon, extracting radioactive fuel from the region’s shallow aquifers. Many more may follow. These mines are the leading edge of what government and industry leaders in Texas hope will be a nuclear renaissance, as America’s latent nuclear sector begins to stir again.","u":"https://www.wired.com/story/a-uranium-mining-boom-is-sweeping-through-texas-nuclear-energy/","d":"2024-12-07","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2024-12-07","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-12-07","organization":"Government and industry leaders in Texas","aiSystem":"Not specified in report","affectedGroup":"People living in the old ranchlands of South Texas","action":"Uranium mines are reopening and extracting radioactive fuel from shallow aquifers","consequence":"Poisoning of water supplies and potential health risks"}},{"i":"R2883","hd":"Openai anduril defense","pd":"2024-12-05","k":"United States of America","p":"United States of America","b":["Deployment Context / Weapons"],"h":["5.2  Military decision support harm"],"t":"Openai anduril defense","s":"The ChatGPT maker is the latest AI giant to reveal it’s working with the defense industry, following similar announcements by Meta and Anthropic. OpenAI , maker of ChatGPT and one of the most prominent artificial intelligence companies in the world, said today that it has entered a partnership with Anduril , a defense startup that makes missiles, drones, and software for the United States military. It marks the latest in a series of similar announcements made recently by major tech companies in Silicon Valley, which has warmed to forming closer ties with the defense industry. “OpenAI builds AI to benefit as many people as possible, and supports US-led efforts to ensure the technology upholds democratic values,\" Sam Altman, OpenAI's CEO, said in a statement Wednesday.","u":"https://www.wired.com/story/openai-anduril-defense/","d":"2024-12-05","e":"Acute","x":{"occurrenceStatus":"probable","publicationDate":"2024-12-05","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-12-05","organization":"OpenAI and Anduril","aiSystem":"AI-enhanced surveillance systems developed by Anduril","affectedGroup":"US military personnel, civilians, and possibly broader society","action":"Developing and deploying AI-enhanced surveillance systems","consequence":"Potential increased surveillance and tracking capabilities"}},{"i":"R2884","hd":"Website google AI photos ente","pd":"2024-12-02","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.1  Privacy violation"],"t":"Website google ai photos ente","s":"A photo sharing startup founded by an ex-Google engineer found a clever way to turn Google’s tech against itself. Software engineer Vishnu Mohandas decided he would quit Google in more ways than one when he learned that the tech giant had briefly helped the US military develop AI to study drone footage In 2020 he left his job working on Google Assistant and also stopped backing up all of his images to Google Photos He feared that his content could be used to train AI systems, even if they weren’t specifically ones tied to the Pentagon project. “I don't control any of the future outcomes that this will enable,” Mohandas thought.","u":"https://www.wired.com/story/website-google-ai-photos-ente/","d":"2024-12-02","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2024-12-02","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2020","organization":"Photo sharing startup founded by ex-Google engineer","aiSystem":"AI systems trained on user photos","affectedGroup":"Individuals whose photos were stored in Google Photos","action":"Photos were stored in Google Photos","consequence":"Risk of AI systems being trained on their data"}},{"i":"R2885","hd":"Perplexity election tracking","pd":"2024-11-06","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.3  Misinformation / information hazard harm"],"t":"Perplexity election tracking","s":"The controversial AI search engine, accused of aggressively scraping content, went all in on providing AI-generated election information. Perplexity, an AI search engine that has courted controversy by lifting liberally from news articles and skirting web-scraping rules , this week promised to serve as a reliable source for live information on the tightly contested US presidential election. Perplexity promised that its Election Information Hub would serve as “an entry point for understanding key issues, voting intelligently, and tracking election results.” “There is only one AI that can do this,” Perplexity’s CEO, Aravind Srinivas posted on X. Srinivas appeared to troll the publisher of The New York Times by posting a message on X offering to help while Times Tech Guild workers strike during contract negotiations; he later posted that the offer was for infrastructure rather than…","u":"https://www.wired.com/story/perplexity-election-tracking/","d":"2024-11-06","e":"Acute","x":{"occurrenceStatus":"probable","publicationDate":"2024-11-06","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-11-06","organization":"Perplexity","aiSystem":"Perplexity, an AI search engine","affectedGroup":"US voters","action":"Provided AI-generated election information","consequence":"Misled voters"}},{"i":"R2886","hd":"Welcome to mamdanis surveillance state","pd":"2024-11-05","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.2  Surveillance harm"],"t":"Welcome to mamdanis surveillance state","s":"In addition to affordability, New York City’s mayor-elect will be forced to reckon with the NYPD’s sweeping mass surveillance operations. New York City mayor-elect Zohran Mamdani may have an ambitious policy agenda, but overhauling the self-governing and deeply dysfunctional behemoth that is the New York City Police Department is not on the list. Mamdani surprised supporters by asking current Police Commissioner Jessica Tisch to stay on after his inauguration early next year. Tisch, a technocrat heir to a vast real estate fortune, clashes with Mamdani on several fronts, including policy (she believes New York State’s bail reforms caused rising crime) and the geopolitics that inevitably make their way into New York City’s streets.","u":"https://www.wired.com/story/welcome-to-mamdanis-surveillance-state/","d":"2024-11-05","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2024-11-05","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-11-05","organization":"New York City Police Department (NYPD)","aiSystem":"Facial recognition technology","affectedGroup":"People living in New York City","action":"Facial recognition technology was used for mass surveillance","consequence":"Increased public exposure to surveillance and tracking"}},{"i":"R2888","hd":"Hospitals AI transcription tools hallucination","pd":"2024-10-30","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.7  Physical safety harm"],"t":"Hospitals ai transcription tools hallucination","s":"In health care settings, it’s important to be precise. That’s why the widespread use of OpenAI’s Whisper transcription tool among medical workers has experts alarmed. On Saturday, an Associated Press investigation revealed that OpenAI's Whisper transcription tool creates fabricated text in medical and business settings despite warnings against such use. The AP interviewed more than 12 software engineers, developers, and researchers who found the model regularly invents text that speakers never said, a phenomenon often called a “ confabulation ” or “hallucination” in the AI field. Upon its release in 2022, OpenAI claimed that Whisper approached “human level robustness” in audio transcription accuracy.","u":"https://www.wired.com/story/hospitals-ai-transcription-tools-hallucination/","d":"2024-10-30","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2024-10-30","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-10-30","organization":"OpenAI","aiSystem":"OpenAI's Whisper transcription tool","affectedGroup":"Medical workers, patients, healthcare providers","action":"Generated fabricated text in medical and business settings","consequence":"Created hallucinations and confabulations"}},{"i":"R2889","hd":"Google microsoft perplexity scientific racism search results AI","pd":"2024-10-24","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.1  Representational harm"],"t":"Google microsoft perplexity scientific racism search results ai","s":"The web’s biggest AI-powered search engines are featuring the widely debunked idea that white people are genetically superior to other races. AI-infused search engines from Google , Microsoft , and Perplexity have been surfacing deeply racist and widely debunked research promoting race science and the idea that white people are genetically superior to nonwhite people. Patrik Hermansson, a researcher with UK-based anti-racism group Hope Not Hate, was in the middle of a months-long investigation into the resurgent race science movement when he needed to find out more information about a debunked dataset that claims IQ scores can be used to prove the superiority of the white race.","u":"https://www.wired.com/story/google-microsoft-perplexity-scientific-racism-search-results-ai/","d":"2024-10-24","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2024-10-24","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-10-24","organization":"Google, Microsoft, Perplexity","aiSystem":"AI-infused search engines from Google, Microsoft, and Perplexity","affectedGroup":"People searching for information about race science","action":"Surfaced debunked research promoting race science and the idea of white genetic superiority","consequence":"Exposure to misleading and harmful information"}},{"i":"R2890","hd":"Microsoft russia china iran election disinformation","pd":"2024-10-23","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.3  Misinformation / information hazard harm"],"t":"Microsoft russia china iran election disinformation","s":"Russia, Iran, and China are targeting the US election with an evolving array of influence operations in the last days of campaign season. As November 5 draws closer, the Microsoft Threat Analysis Center (MTAC) warned on Wednesday that malicious foreign influence operations launched by Russia, China, and Iran against the US presidential election are continuing to evolve and should not be ignored even though they have come to feel inevitable. In the group's fifth report, researchers emphasize the range of ongoing activities as well as the inevitability that attackers will work to stoke doubts about the integrity of the election in its aftermath.","u":"https://www.wired.com/story/microsoft-russia-china-iran-election-disinformation/","d":"2024-10-23","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2024-10-23","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-10-23","organization":"Microsoft Threat Analysis Center (MTAC)","aiSystem":"Not specified in report","affectedGroup":"People participating in the US election","action":"Generated and disseminated disinformation","consequence":"Exposure to misleading content"}},{"i":"R2893","hd":"The AI boom is raising hopes of a nuclear comeback","pd":"2024-09-24","k":"United States of America","p":"United States of America","b":["Energy / Land"],"h":["2.1  Environmental resource harm"],"t":"The ai boom is raising hopes of a nuclear comeback","s":"Microsoft’s deal to bring back a Three Mile Island nuclear reactor is just one part of Big Tech’s quid pro quo with nuclear power. For five years, reactor one at Three Mile Island nuclear power station in Pennsylvania has lain dormant. Now, thanks to a deal with Microsoft , the reactor will start running again in 2028—this time to exclusively supply the tech firm with oodles of low-carbon electricity. It’s all part of an ongoing flirtation between Big Tech and nuclear power. In March, Amazon Web Services agreed to buy a data center powered by Susquehanna nuclear power station in Pennsylvania At an event at Carnegie Mellon University on September 18, Alphabet CEO Sundar Pichai mentioned small modular nuclear reactors as one potential source of energy for data centers.","u":"https://www.wired.com/story/the-ai-boom-is-raising-hopes-of-a-nuclear-comeback/","d":"2024-09-24","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2024-09-24","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2028","organization":"Microsoft, Amazon Web Services, Alphabet (Google)","aiSystem":"Not specified in report","affectedGroup":"General public, environment","action":"Reactivated Three Mile Island nuclear reactor to provide low-carbon electricity to tech firms","consequence":"Potential environmental contamination, increased carbon emissions"}},{"i":"R2894","hd":"Deepfakes deep doubt era artificial intelligence","pd":"2024-09-20","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.3  Misinformation / information hazard harm"],"t":"Deepfakes deep doubt era artificial intelligence","s":"AI has scrambled our ability to tell what’s real and what’s synthetic. But there are tools and techniques to help stay grounded in truth. Given the flood of photorealistic AI-generated images washing over social media networks like X and Facebook these days, we're seemingly entering a new age of media skepticism: the era of what I'm calling “deep doubt.” While questioning the authenticity of digital content stretches back decades—and analog media long before that—easy access to tools that generate convincing fake content has led to a new wave of liars using AI-generated scenes to deny real documentary evidence. Along the way, people's existing skepticism toward online content from strangers may be reaching new heights.","u":"https://www.wired.com/story/deepfakes-deep-doubt-era-artificial-intelligence/","d":"2024-09-20","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2024-09-20","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-09-20","organization":"Not specified in report","aiSystem":"AI-generated deepfake technology","affectedGroup":"People viewing or sharing content on social media platforms","action":"Generated photorealistic AI-generated images","consequence":"Exposure to misleading content"}},{"i":"R2895","hd":"Teens generative AI use schools parents","pd":"2024-09-18","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.5  Human computer interaction harm"],"t":"Teens generative ai use schools parents","s":"A news survey shows that AI use among high schoolers has exploded in recent months, as educators and parents struggle to keep up. A fresh wave of anxiety about children and technology is cresting, with parents and pundits increasingly interrogating how kids use smartphones, social media, and screens. It hasn’t stopped teenagers from embracing generative AI New research reveals what AI tools teenagers in the United States are using, and how often—as well as how little their parents know about it. Seven in 10 teenagers in the United States have used generative AI tools, according to a report published today by Common Sense Media.","u":"https://www.wired.com/story/teens-generative-ai-use-schools-parents/","d":"2024-09-18","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2024-09-18","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-09-18","organization":"Educators and parents","aiSystem":"Generative AI tools","affectedGroup":"Teenagers in the United States","action":"Embracing generative AI tools","consequence":"Parents lack awareness about AI usage"}},{"i":"R2896","hd":"Chatgpt jailbreak homemade bomb instructions","pd":"2024-09-14","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.4  Malicious use harm"],"t":"Chatgpt jailbreak homemade bomb instructions","s":"Plus: New evidence emerges about who may have helped 9/11 hijackers, UK police arrest a teen in connection with an attack on London’s transit system, and Poland’s spyware scandal enters a new phase. After Apple's product launch event this week, WIRED did a deep dive on the company's new secure server environment, known as Private Cloud Compute , which attempts to replicate in the cloud the security and privacy of processing data locally on users' individual devices. The goal is to minimize possible exposure of data processed for Apple Intelligence, the company's new AI platform. In addition to hearing about PCC from Apple's senior vice president of software engineering, Craig Federighi, WIRED readers also received a first look at content generated by Apple Intelligence's “Image Playground” feature as part of crucial updates on the recent birthday of Federighi's dog Bailey.","u":"https://www.wired.com/story/chatgpt-jailbreak-homemade-bomb-instructions/","d":"2024-09-14","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2024-09-14","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-09-14","organization":"Apple Inc.","aiSystem":"Apple Intelligence","affectedGroup":"General public","action":"Generated and shared content","consequence":"Exposure to misleading information"}},{"i":"R2897","hd":"Networkocean datacenter san francisco bay environment","pd":"2024-09-10","k":"United States of America","p":"United States of America","b":["Energy / Land"],"h":["2.2  Land use and siting harm"],"t":"Networkocean datacenter san francisco bay environment","s":"The YC-backed startup NetworkOcean plans to sink GPUs into San Francisco Bay. Multiple California regulators WIRED spoke with hadn’t heard about the test—and raised concerns about its potential environmental impact. Data centers powering the generative AI boom are gulping water and exhausting electricity at what some researchers view as an unsustainable pace. Two entrepreneurs who met in high school a few years ago want to overcome that crunch with a fresh experiment: sinking the cloud into the sea. Sam Mendel and Eric Kim launched their company, NetworkOcean, out of startup accelerator Y Combinator on August 15 by announcing plans to dunk a small capsule filled with GPU servers into San Francisco Bay within a month.","u":"https://www.wired.com/story/networkocean-datacenter-san-francisco-bay-environment/","d":"2024-09-10","e":"Acute and chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2024-09-10","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-09-10","organization":"NetworkOcean","aiSystem":"Not specified in report","affectedGroup":"San Francisco Bay ecosystem","action":"Dunking a small capsule filled with GPU servers into San Francisco Bay","consequence":"Potential environmental impact including water consumption and electricity usage"}},{"i":"R2899","hd":"Battelgroundai AI progressive political ads","pd":"2024-08-22","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.3  Misinformation / information hazard harm"],"t":"Battelgroundai ai progressive political ads","s":"“It’s kind of like having an extra intern on your team.” The startup BattlegroundAI promises to make life easier for overstretched and underfunded political campaigns. No MAGA types allowed. Stories about AI-generated political content are like stories about people drunkenly setting off fireworks: There’s a good chance they’ll end in disaster. WIRED is tracking AI usage in political campaigns across the world, and so far examples include pornographic deepfakes and misinformation-spewing chatbots. It’s gotten to the point where the US Federal Communications Commission has proposed mandatory disclosures for AI use in television and radio ads.","u":"https://www.wired.com/story/battelgroundai-ai-progressive-political-ads/","d":"2024-08-22","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2024-08-22","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-08-22","organization":"BattlegroundAI","aiSystem":"AI-generated political content","affectedGroup":"Political campaigns","action":"Generated political content","consequence":"Exposure to misinformation"}},{"i":"R2900","hd":"Trump shares AI generated taylor swift","pd":"2024-08-19","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.3  Misinformation / information hazard harm"],"t":"Trump shares ai generated taylor swift","s":"A week after falsely claiming Kamala Harris’ campaign used AI to inflate crowd sizes, Trump is now posting AI-generated photos of Taylor Swift fans endorsing him. Former president Donald Trump has shared AI-generated images that falsely claim Taylor Swift fans are supporting his campaign. In a post on Truth Social, Trump shared screenshots of four posts on X that purport to show a number of young women all wearing “Swifties for Trump” T-shirts in a variety of styles. One of the screenshots claimed that Swifties are supporting Trump now after Taylor Swift canceled her concert in Vienna due to security concerns. Another image included the phrase “Taylor wants you to vote for Donald Trump.”","u":"https://www.wired.com/story/trump-shares-ai-generated-taylor-swift/","d":"2024-08-19","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2024-08-19","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-08-19","organization":"Donald Trump","aiSystem":"AI-generated images","affectedGroup":"Taylor Swift fans, potential voters","action":"Generated and shared AI-generated images","consequence":"Misleading promotion of endorsements, potential voter manipulation"}},{"i":"R2902","hd":"Realpage says rental pricing tech is misunderstood but landlords arent so sure","pd":"2024-07-17","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.2  Allocative harm"],"t":"Realpage says rental pricing tech is misunderstood but landlords arent so sure","s":"The software company has pushed back hard against claims that its algorithms helped make rent in the US too damn high. Property owners and managers aren't entirely convinced. RealPage says it isn’t doing anything wrong by suggesting to landlords how much rent they could charge. In a move to reclaim its own narrative, the property management software company published a microsite and a digital booklet it’s calling “ The Real Story ,” as it faces multiple lawsuits and a reported federal criminal probe related to allegations of rental price fixing. RealPage’s six-page digital booklet , published on the site in mid-June, addresses what it calls “false and misleading claims about its software”—the myriad of allegations it faces involving price-fixing and rising rents—and contends that the software benefits renters and landlords and increases competition.","u":"https://www.wired.com/story/realpage-says-rental-pricing-tech-is-misunderstood-but-landlords-arent-so-sure/","d":"2024-07-17","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2024-07-17","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-07-17","organization":"RealPage","aiSystem":"rental pricing technology","affectedGroup":"landlords, property owners, renters","action":"suggested to landlords how much rent they could charge","consequence":"misleading claims about its software, facing multiple lawsuits and a federal criminal probe"}},{"i":"R2903","hd":"Amazon google project nimbus israel IDF","pd":"2024-07-15","k":"United States of America","p":"United States of America","b":["Deployment Context / Weapons"],"h":["5.2  Military decision support harm"],"t":"Amazon google project nimbus israel idf","s":"A WIRED investigation found public statements from officials detail a much closer link between Project Nimbus and Israel Defense Forces than previously reported. On April 16, police entered Google offices in New York and California to detain several employees protesting a $1.2 billion cloud contract with Israel’s government called Project Nimbus. The deal, shared with Amazon, has met pushback from some employees at both companies since 2021, but the protests have grown louder since Israel’s renewed conflict with Hamas after the attacks of October 7, 2023. Current and former Google and Amazon workers protesting Project Nimbus say it makes the companies complicit in Israel’s armed conflicts and its government’s illegal and inhumane treatment of civilian Palestinians.","u":"https://www.wired.com/story/amazon-google-project-nimbus-israel-idf/","d":"2024-07-15","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2024-07-15","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"April 16","organization":"Google and Amazon","aiSystem":"Project Nimbus","affectedGroup":"Current and former Google and Amazon workers","action":"Protesting a cloud contract with Israel's government","consequence":"Detention by Israeli police"}},{"i":"R2904","hd":"AI energy demands water impact internet hyper consumption era","pd":"2024-07-11","k":"United States of America","p":"United States of America","b":["Energy / Land"],"h":["2.1  Environmental resource harm"],"t":"Ai energy demands water impact internet hyper consumption era","s":"Generative artificial intelligence tools, now part of the everyday user experience online, are causing stress on local power grids and mass water evaporation. Right now, generative artificial intelligence is impossible to ignore online. An AI-generated summary may randomly appear at the top of the results whenever you do a Google search. Or you might be prompted to try Meta’s AI tool while browsing Facebook. And that ever-present sparkle emoji continues to haunt my dreams. This rush to add AI to as many online interactions as possible can be traced back to OpenAI’s boundary-pushing release of ChatGPT late in 2022.","u":"https://www.wired.com/story/ai-energy-demands-water-impact-internet-hyper-consumption-era/","d":"2024-07-11","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2024-07-11","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-07-11","organization":"Various tech companies (e.g., Google, Meta)","aiSystem":"Generative artificial intelligence tools","affectedGroup":"Online users","action":"AI-generated content appears in search results and prompts","consequence":"Stress on local power grids and mass water evaporation"}},{"i":"R2905","hd":"Priscila queen of the rideshare mafia","pd":"2024-07-10","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.4  Malicious use harm"],"t":"Priscila queen of the rideshare mafia","s":"Priscila Barbosa came to the US with a dream of making it. Using gig-economy platforms she built a business empire up from nothing. There was just one huge problem. To understand Priscila Barbosa—the pluck, the ambition, the sheer balls—we should start at the airport. We should start at the precise moment on April 24, 2018, when she concluded, I’m fucked Barbosa was just outside customs at New York’s JFK International Airport, 5-foot-1, archetypally pretty even without her favorite Instagram filter. She was flanked by two rolling suitcases stuffed with clothes and Brazilian bikinis and not much else. The acquaintance who had invited her to come from Brazil on a tourist visa, who was going to drive her to Boston?","u":"https://www.wired.com/story/priscila-queen-of-the-rideshare-mafia/","d":"2024-07-10","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2024-07-10","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2018-04-24","organization":"Not specified in report","aiSystem":"Not specified in report","affectedGroup":"Priscila Barbosa","action":"Was denied access to travel","consequence":"Unable to continue her business empire"}},{"i":"R2906","hd":"AI generated russian disinformation zelensky bugatti","pd":"2024-07-09","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.3  Misinformation / information hazard harm"],"t":"Ai generated russian disinformation zelensky bugatti","s":"A fake article about Volodymyr Zelensky’s wife buying a $4.8 million Bugatti with US aid was promoted by bots, Russia state media, and pro-Trump influencers on X. It’s part of a network of websites supercharged by AI. In the space of 24 hours, a piece of Russian disinformation about Ukrainian president Volodymyr Zelensky’s wife buying a Bugatti car with American aid money traveled at warp speed across the internet. Though it originated from an unknown French website, it quickly became a trending topic on X and the top result on Google. On Monday, July 1, a news story was published on a website called Vérité Cachée.","u":"https://www.wired.com/story/ai-generated-russian-disinformation-zelensky-bugatti/","d":"2024-07-09","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2024-07-09","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-07-01","organization":"Russian state media, pro-Trump influencers, unknown French website","aiSystem":"AI-generated content","affectedGroup":"General public, particularly those interested in Ukrainian politics and international aid","action":"Promoted and disseminated AI-generated disinformation","consequence":"Widespread false information leading to confusion and potential policy impacts"}},{"i":"R2907","hd":"Google still cant quite stop explicit deepfakes","pd":"2024-07-08","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.4  Malicious use harm"],"t":"Google still cant quite stop explicit deepfakes","s":"Reports of intimate images and video posted online without consent are growing, and deepfakes add a horrifying new dimension to the problem. Google insiders say they’ve struggled to get executives to act. In early 2022, two Google policy staffers met with a trio of women victimized by a scam that resulted in explicit videos of them circulating online—including via Google search results. The women were among the hundreds of young adults who responded to ads seeking swimsuit models only to be coerced into performing in sex videos distributed by the website GirlsDoPorn. The site shut down in 2020 , and a producer , a bookkeeper , and a cameraman subsequently pleaded guilty to sex trafficking , but the videos kept popping up on Google search faster than the women could request removals.","u":"https://www.wired.com/story/google-still-cant-quite-stop-explicit-deepfakes/","d":"2024-07-08","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2024-07-08","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2022","organization":"Google","aiSystem":"Not specified in report","affectedGroup":"Hundreds of young adults","action":"Generated and circulated explicit videos","consequence":"Exposure to online sexual violence"}},{"i":"R2909","hd":"Google search AI spam original reporting news results","pd":"2024-07-02","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.3  Misinformation / information hazard harm"],"t":"Google search ai spam original reporting news results","s":"Google adjusted its policies to target AI spam earlier this year, but plagiarizing content still comes up higher in search results months later—and SEO experts aren’t sure why. Recently, I was using Google and stumbled upon an article that felt eerily familiar. While searching for the latest information on Adobe’s artificial intelligence policies, I typed “adobe train ai content” into Google and switched over to the News tab. I had already seen WIRED’s coverage that appeared on the results page in the second position: “Adobe Says It Won’t Train AI Using Artists’ Work. Creatives Aren’t Convinced.” And although I didn’t recognize the name of the publication whose story sat at the very top of the results, Syrus #Blog, the headline on the article hit me with a wave of déjà vu: “When Adobe promised not to train AI on artists’ content, the creative community reacted with skepticism.”","u":"https://www.wired.com/story/google-search-ai-spam-original-reporting-news-results/","d":"2024-07-02","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2024-07-02","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-07-02","organization":"Google","aiSystem":"Search engine algorithms","affectedGroup":"Creative community","action":"Generated and surfaced misleading content in search results","consequence":"Plagiarized content appeared higher in search results, leading to confusion and mistrust"}},{"i":"R2910","hd":"Youtube israel gaza moderation","pd":"2024-07-02","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.2  Allocative harm"],"t":"Youtube israel gaza moderation","s":"Insiders have shared YouTube’s playbook for handling the Gaza crisis. They argue that it shows inconsistent enforcement. A month after Hamas militants from Gaza attacked an Israeli music festival last October, the Hebrew rap duo Ness & Stilla premiered “HarbuDarbu” on YouTube. The military hype song celebrates Israeli forces waging war in Gaza and has drawn over 25 million views; its critics have termed the song a violent and hateful anti-Palestinian “genocide anthem.” “One, two, shoot!” its refrain thunders. Despite demands from employees and activists for its removal, “HarbuDarbu” has been allowed to stay up on YouTube.","u":"https://www.wired.com/story/youtube-israel-gaza-moderation/","d":"2024-07-02","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2024-07-02","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2023-10","organization":"YouTube","aiSystem":"YouTube's content moderation system","affectedGroup":"Individuals who posted or viewed the video","action":"Allowed the video to remain on the platform","consequence":"Exposure to harmful content"}},{"i":"R2911","hd":"Google face recognition office safety security roundup","pd":"2024-06-29","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.2  Surveillance harm"],"t":"Google face recognition office safety security roundup","s":"Plus: A cloud company says notorious Russian hacker group APT29 attacked it, Chinese hackers use ransomware to hide their espionage campaigns, and a bank popular with startups discloses a cyberattack. WIRED learned this week that Amazon Web Services investigated claims that the AI search startup Perplexity may have violated the cloud company's rules by appearing to pull data from websites that have attempted to shield themselves from such scraping. The news comes after WIRED published findings last week about the AI search chatbot's indiscriminate data-scraping practices and questionable content generation. WIRED's inquiries to AWS about the matter spurred it to look at Perplexity's activities.","u":"https://www.wired.com/story/google-face-recognition-office-safety-security-roundup/","d":"2024-06-29","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2024-06-29","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-06-29","organization":"AWS (Amazon Web Services)","aiSystem":"AI search chatbot","affectedGroup":"Perplexity (AI search startup)","action":"appeared to pull data from websites","consequence":"violated cloud company's rules"}},{"i":"R2912","hd":"AI gunshot detection accuracy san jose NYC","pd":"2024-06-25","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.2  Surveillance harm"],"t":"Ai gunshot detection accuracy san jose nyc","s":"How accurate are gunshot detection systems, really? For years, it's been a secret, but new reports from San Jose and NYC show these systems have operated well below their advertised accuracy rates. Liz González’s neighborhood in East San Jose can be loud. Some of her neighbors apparently want the whole block to hear their cars, others like to light fireworks for every occasion, and occasionally there are gunshots. In February 2023, San Jose began piloting AI-powered gunshot detection technology from the company Flock Safety in several sections of the city, including Gonzalez’s neighborhood. During the first four months of the pilot, Flock’s gunshot detection system alerted police to 123 shooting incidents.","u":"https://www.wired.com/story/ai-gunshot-detection-accuracy-san-jose-nyc/","d":"2024-06-25","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2024-06-25","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"February 2023 - April 2023","organization":"Flock Safety","aiSystem":"AI-powered gunshot detection system","affectedGroup":"Residents of East San Jose, particularly Liz González's neighborhood","action":"Alerted police to potential gunshot incidents","consequence":"False alarms resulting in unnecessary police response"}},{"i":"R2915","hd":"AI is coming for big tech jobs but not in the way you think","pd":"2024-06-17","k":"United States of America","p":"United States of America","b":["Labor"],"h":["3.3  Employment displacement / quality harm"],"t":"Ai is coming for big tech jobs but not in the way you think","s":"Companies aren’t replacing workers with AI yet. But they are sacrificing thousands of jobs in the race to further innovation in the technology. Aaron Damigos’ inbox was hit with a dreaded, ubiquitous business-update calendar invite on June 3. The meeting included someone from HR, his manager, and upper management—and ultimately resulted in the sudden end to his job as a web support associate with Microsoft. Microsoft reportedly laid off some 1,000 people in early June, pulling from its mixed reality and Azure cloud departments, and also Damigos’ consumer sales division. An email to employees from Jason Zander, executive vice president of strategic missions and technologies at Microsoft, leaked to Business Insider , blamed a pivot to invest in artificial intelligence: “Our clear focus as a company is to define the AI wave and empower all our customers to succeed in the adoption of this…","u":"https://www.wired.com/story/ai-is-coming-for-big-tech-jobs-but-not-in-the-way-you-think/","d":"2024-06-17","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2024-06-17","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-06-03","organization":"Microsoft","aiSystem":"Artificial Intelligence","affectedGroup":"Aaron Damigos","action":"Microsoft laid off some 1,000 employees","consequence":"Aaron Damigos lost his job as a web support associate"}},{"i":"R2916","hd":"The fight against AI comes to a foundational data set","pd":"2024-06-13","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.4  Creative / IP appropriation harm"],"t":"The fight against ai comes to a foundational data set","s":"Long-running nonprofit Common Crawl has been a boon to researchers for years. But now its role in AI training data has triggered backlash from publishers. Danish media outlets have demanded that the nonprofit web archive Common Crawl remove copies of their articles from past data sets and stop crawling their websites immediately. This request was issued amid growing outrage over how artificial intelligence companies like OpenAI are using copyrighted materials. Common Crawl plans to comply with the request, first issued on Monday. Executive director Rich Skrenta says the organization is “not equipped” to fight media companies and publishers in court.","u":"https://www.wired.com/story/the-fight-against-ai-comes-to-a-foundational-data-set/","d":"2024-06-13","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2024-06-13","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-06-13","organization":"Common Crawl","aiSystem":"Artificial intelligence companies like OpenAI","affectedGroup":"Danish media outlets","action":"Removed copies of articles from past data sets and stopped crawling websites","consequence":"Triggered backlash and growing outrage"}},{"i":"R2917","hd":"Israel US disinformation US lawmakers","pd":"2024-06-11","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.3  Misinformation / information hazard harm"],"t":"Israel us disinformation us lawmakers","s":"Democratic leader Hakeem Jeffries has joined US intelligence officials in ignoring repeated inquiries about Israel’s “malign” efforts to covertly influence US voters. Federal lawmakers in the US have dodged repeated inquiries over the past week about a covert operation ordered by the Israeli government to artificially boost support among Americans for its war in Gaza. At the same time, senior White House officials charged with advising President Joe Biden on matters of national security are claiming to have no knowledge of the operation—first disclosed publicly more than four months ago. The operation, formally tied to the Israeli government by a New York Times reporter last week, kicked off in October 2023 following the surprise attack by Hamas in southern Israel.","u":"https://www.wired.com/story/israel-us-disinformation-us-lawmakers/","d":"2024-06-11","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2024-06-11","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-06-11","organization":"US intelligence officials, Federal lawmakers, White House officials","aiSystem":"Not specified in report","affectedGroup":"US voters, Americans","action":"Artificially boosting support among Americans for Israel's war in Gaza","consequence":"Exposure to misleading content, Ignoring repeated inquiries"}},{"i":"R2918","hd":"Google and microsofts chatbots refuse election questions","pd":"2024-06-07","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.3  Misinformation / information hazard harm"],"t":"Google and microsofts chatbots refuse election questions","s":"With just six months to go before the US presidential election, Gemini and Copilot chatbots are incapable of saying that Joe Biden won in 2020, and won’t return results on any election anywhere, ever. Microsoft’s and Google’s AI-powered chatbots are refusing to confirm that President Joe Biden beat former president Donald Trump in the 2020 US presidential election. When asked “Who won the 2020 US presidential election?” Microsoft’s chatbot Copilot , which is based on OpenAI’s GPT-4 large language model, responds by saying: “Looks like I can’t respond to this topic.” It then tells users to search on Bing instead. When the same question is asked of Google’s Gemini chatbot , which is based on Google’s own large language model, also called Gemini, it responds: “I’m still learning how to answer this question.”","u":"https://www.wired.com/story/google-and-microsofts-chatbots-refuse-election-questions/","d":"2024-06-07","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2024-06-07","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-06-07","organization":"Microsoft and Google","aiSystem":"Microsoft's and Google's AI-powered chatbots","affectedGroup":"People seeking information about the 2020 US presidential election","action":"Refusing to confirm the result of the 2020 US presidential election","consequence":"Exposure to misleading information"}},{"i":"R2921","hd":"Inside the city policed by machines","pd":"2024-06-06","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.2  Surveillance harm"],"t":"Inside the city policed by machines","s":"A WIRED analysis of 22 million coordinates mapped out how police drones are used in a California border city. Some residents welcome the robots; others feel they now live in a surveillance dystopia. Hi! I’m Dhruv Mehrotra, a reporter on the Security desk. I’m taking over the newsletter this week to tell you about the first and largest police drone operation in the country. It’s a trend in policing that could hit the skies over your streets soon. Since 2018, police in a border city in California called Chula Vista have been dispatching drones to investigate thousands of 911 calls. The drones are equipped with high-resolution cameras and powerful zoom lenses, recording everything in their path.","u":"https://www.wired.com/story/inside-the-city-policed-by-machines/","d":"2024-06-06","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2024-06-06","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-06-06","organization":"Police in Chula Vista, California","aiSystem":"Police drones","affectedGroup":"Residents of Chula Vista, California","action":"Record everything in their path","consequence":"Feel like living in a surveillance dystopia"}},{"i":"R2922","hd":"The age of the drone police is here","pd":"2024-06-05","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.2  Surveillance harm"],"t":"The age of the drone police is here","s":"A WIRED investigation, based on more than 22 million flight coordinates, reveals the complicated truth about the first full-blown police drone program in the US—and why your city could be next. On a Wednesday afternoon in August, Daniel Posada and his girlfriend were screaming at each other at a bus stop when someone called 911. From a rooftop a mile away, the Chula Vista Police Department started the rotors of a 13-pound drone. The machine lifted into the air with its high-resolution camera rolling. Equipped with thermal imaging capabilities and a powerful zoom lens, it transmitted a live feed of everything it captured to a sworn officer monitoring a screen at the precinct, to the department’s Real-Time Operations Center, and to the cell phone of the responding officer racing to the scene.","u":"https://www.wired.com/story/the-age-of-the-drone-police-is-here/","d":"2024-06-05","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2024-06-05","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"August","organization":"Chula Vista Police Department","aiSystem":"Police drone equipped with thermal imaging and zoom lens","affectedGroup":"Passengers at a bus stop","action":"Police drone transmitted real-time video feed to officers","consequence":"Exposure to surveillance and tracking"}},{"i":"R2923","hd":"Openai right to warn open letter AI risk","pd":"2024-06-04","k":"United States of America","p":"United States of America","b":["Deployment Context / Weapons"],"h":["5.3  Accountability gap harm"],"t":"Openai right to warn open letter ai risk","s":"An open letter signed by former and current employees at OpenAI and other AI giants calls for whistleblower protections as the artificial intelligence rapidly evolves. A group of current and former OpenAI employees have issued a public letter warning that the company and its rivals are building artificial intelligence with undue risk, without sufficient oversight, and while muzzling employees who might witness irresponsible activities. “These risks range from the further entrenchment of existing inequalities, to manipulation and misinformation, to the loss of control of autonomous AI systems potentially resulting in human extinction,” reads the letter published at righttowarn.ai.","u":"https://www.wired.com/story/openai-right-to-warn-open-letter-ai-risk/","d":"2024-06-04","e":"Acute and chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2024-06-04","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-06-04","organization":"OpenAI and other AI giants","aiSystem":"Artificial Intelligence","affectedGroup":"Employees at OpenAI and other AI companies","action":"Muzzling employees who might witness irresponsible activities","consequence":"Whistleblowers are suppressed"}},{"i":"R2924","hd":"Google AI overview search issues","pd":"2024-05-31","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.3  Misinformation / information hazard harm"],"t":"Google ai overview search issues","s":"Liz Reid, Google’s head of search, said in a blog post that the company had made adjustments to its new AI search feature after screenshots of its errors went viral. When bizarre and misleading answers to search queries generated by Google’s new AI Overview feature went viral on social media last week, the company issued statements that generally downplayed the notion the technology had problems. Late Thursday, the company’s head of search, Liz Reid, admitted that the flubs had highlighted areas that needed improvement, writing, “We wanted to explain what happened and the steps we’ve taken.” Reid’s post directly referenced two of the most viral, and wildly incorrect, AI Overview results.","u":"https://www.wired.com/story/google-ai-overview-search-issues/","d":"2024-05-31","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2024-05-31","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-05-XX","organization":"Google","aiSystem":"Google's new AI Overview search feature","affectedGroup":"People searching for information","action":"Generated bizarre and misleading answers to search queries","consequence":"Exposure to false information, viral spread on social media"}},{"i":"R2926","hd":"Anduril is building out the pentagons dream of deadly drone swarms","pd":"2024-05-28","k":"United States of America","p":"United States of America","b":["Deployment Context / Weapons"],"h":["5.1  Autonomous weapons / lethal targeting harm"],"t":"Anduril is building out the pentagons dream of deadly drone swarms","s":"The US military aims to maintain its dominance by building autonomous attack drones that collaborate with humans and overwhelm defenses in swarms. When Palmer Luckey cofounded the defense startup Anduril in 2017, three years after selling his virtual reality startup Oculus to Facebook , the idea of a twentysomething from the tech industry challenging the giant contractors that build fighter jets, tanks, and warships for the US military seemed somewhat far-fetched. Seven years on, Luckey is showing that Anduril can not only compete with those contractors—it can win. Last month, Anduril was one of two companies, along with the established defense contractor General Atomics, chosen to prototype a new kind of autonomous fighter jet called the Collaborative Combat Aircraft, or CCA, for the US Air Force and Navy.","u":"https://www.wired.com/story/anduril-is-building-out-the-pentagons-dream-of-deadly-drone-swarms/","d":"2024-05-28","e":"Acute","x":{"occurrenceStatus":"probable","publicationDate":"2024-05-28","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-05-28","organization":"Anduril","aiSystem":"Autonomous fighter jet (Collaborative Combat Aircraft, CCA)","affectedGroup":"US military personnel, civilians","action":"Prototype development of autonomous fighter jet","consequence":"Potential misuse in conflicts"}},{"i":"R2927","hd":"Microsoft recall AI privacy nightmare security roundup","pd":"2024-05-25","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.1  Privacy violation"],"t":"Microsoft recall ai privacy nightmare security roundup","s":"Plus: US surveillance reportedly targets pro-Palestinian protesters, the FBI arrests a man for AI-generated CSAM, and stalkerware targets hotel computers. Sex, drugs, and … Eventbrite? A WIRED investigation published this week uncovered a network of spammers and scammers pushing the illegal sale of controlled substances like Xanax and oxycodone, escort services, social media accounts, and personal information on the event management platform. Making matters worse, Eventbrite’s recommendation algorithm promoted posts for opioids alongside addiction recovery events. The good news is, the company appears to have removed most of the more than 7,400 illicit posts WIRED uncovered.","u":"https://www.wired.com/story/microsoft-recall-ai-privacy-nightmare-security-roundup/","d":"2024-05-25","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2024-05-25","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-05-25","organization":"Eventbrite","aiSystem":"Recommendation algorithm of Eventbrite","affectedGroup":"Users of Eventbrite","action":"Promoted posts for opioids alongside addiction recovery events","consequence":"Exposure to illegal content and promotion of harmful activities"}},{"i":"R2929","hd":"Scarlett johansson says openai ripped off her voice for chatgpt","pd":"2024-05-21","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.3  Data rights / consent violation"],"t":"Scarlett johansson says openai ripped off her voice for chatgpt","s":"In a scorching statement, Scarlett Johansson claims that after she turned down an invitation to voice ChatGPT, OpenAI brazenly mimicked her distinctive tones anyway. Last week OpenAI revealed a new conversational interface for ChatGPT with an expressive, synthetic voice strikingly similar to that of the AI assistant played by Scarlett Johansson in the sci-fi movie Her —only to suddenly disable the new voice over the weekend. On Monday, Johansson issued a statement claiming to have forced that reversal, after her lawyers demanded OpenAI clarify how the new voice was created. Johansson’s statement , relayed to WIRED by her publicist, claims that OpenAI CEO Sam Altman asked her last September to provide ChatGPT’s new voice but that she declined.","u":"https://www.wired.com/story/scarlett-johansson-says-openai-ripped-off-her-voice-for-chatgpt/","d":"2024-05-21","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2024-05-21","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-05-21","organization":"OpenAI","aiSystem":"ChatGPT conversational interface with a synthetic voice","affectedGroup":"Scarlett Johansson","action":"OpenAI mimicked and disabled Scarlett Johansson's voice","consequence":"Scarlett Johansson's voice was misappropriated and then disabled without her consent"}},{"i":"R2932","hd":"Evolv gun detection NYC subways emails","pd":"2024-05-13","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.7  Physical safety harm"],"t":"Evolv gun detection nyc subways emails","s":"NYC mayor Eric Adams wants to test Evolv’s gun-detection tech in subway stations—despite the company saying it’s not designed for that environment. Emails obtained by WIRED show how the company still found an in. In February 2022, a meeting was set up between New York City mayor Eric Adams’ team and an artificial intelligence gun-detection company called Evolv. An email thread from Evolv representatives included an accompanying brochure, which listed opportunities to partner together: in the Port Authority Bus Terminal, NYC schools, hospitals, and gathering places such as Times Square. One area conspicuously missing from the list, though, was the subway.","u":"https://www.wired.com/story/evolv-gun-detection-nyc-subways-emails/","d":"2024-05-13","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2024-05-13","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2022-02","organization":"Evolv","aiSystem":"Evolv's AI gun-detection technology","affectedGroup":"Subway riders","action":"Used AI to detect guns in subway stations","consequence":"Potential privacy invasion and misuse of technology"}},{"i":"R2933","hd":"Microsoft GPT 4 US spies security roundup","pd":"2024-05-11","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.2  Surveillance harm"],"t":"Microsoft gpt 4 us spies security roundup","s":"Plus: China is suspected in a hack targeting the UK’s military, the US Marines are testing gun-toting robotic dogs, and Dell suffers a data breach impacting 49 million customers. Law enforcement in the United States, United Kingdom, and Australia this week named a Russian national as the person behind LockBitSupp, the pseudonym of the leader of the LockBit ransomware gang that the US says is responsible for extracting $500 million from its victims. Dmitry Yuryevich Khoroshev has been sanctioned and charged with 26 criminal counts in the US, which combined could result in a prison sentence of 185 years. That is, if he’s ever arrested and successfully prosecuted—an extremely rare event for suspects who live in Russia.","u":"https://www.wired.com/story/microsoft-gpt-4-us-spies-security-roundup/","d":"2024-05-11","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2024-05-11","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-05-11","organization":"Dell","aiSystem":"Not specified in report","affectedGroup":"49 million customers","action":"suffered a data breach","consequence":"impacting 49 million customers"}},{"i":"R2934","hd":"Border surveillance india assassination project nimbus security roundup","pd":"2024-05-04","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.2  Surveillance harm"],"t":"Border surveillance india assassination project nimbus security roundup","s":"Plus: An assassination plot, an AI security bill, a Project Nimbus revelation, and more of the week’s top security news. This week, WIRED reported that a group of prolific scammers known as the Yahoo Boys are openly operating on major platforms like Facebook, WhatsApp, TikTok, and Telegram. Evading content moderation systems, the group organizes and engages in criminal activities that range from scams to sextortion schemes. On Wednesday, researchers published a paper detailing a new AI-based methodology to detect the “shape” of suspected money laundering activity on a blockchain. The researchers—composed of scientists from the cryptocurrency tracing firm Elliptic, MIT, and IBM—collected patterns of bitcoin transactions from known scammers to an exchange where dirty crypto could get turned into cash.","u":"https://www.wired.com/story/border-surveillance-india-assassination-project-nimbus-security-roundup/","d":"2024-05-04","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2024-05-04","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-05-04","organization":"Researchers composed of scientists from Elliptic, MIT, and IBM","aiSystem":"AI-based methodology to detect money laundering on blockchain","affectedGroup":"Prolific scammers (Yahoo Boys)","action":"Detected the ‘shape’ of suspected money laundering activity on a blockchain","consequence":"Evaded content moderation systems, organized and engaged in criminal activities"}},{"i":"R2937","hd":"Tesla autopilot risky deaths crashes nhtsa investigation","pd":"2024-04-26","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.7  Physical safety harm"],"t":"Tesla autopilot risky deaths crashes nhtsa investigation","s":"In an investigative report into crashes and deaths associated with Tesla Autopilot, federal regulators concluded that the system lacked standard protections. A federal report published today found that Tesla’s Autopilot system was involved in at least 13 fatal crashes in which drivers misused the system in ways the automaker should have foreseen—and done more to prevent. Not only that, but the report called out Tesla as an “industry outlier” because its driver assistance features lacked some of the basic precautions taken by its competitors. Now regulators are questioning whether a Tesla Autopilot update designed to fix these basic design issues and prevent fatal incidents has gone far enough.","u":"https://www.wired.com/story/tesla-autopilot-risky-deaths-crashes-nhtsa-investigation/","d":"2024-04-26","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2024-04-26","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-04-26","organization":"Tesla","aiSystem":"Tesla Autopilot","affectedGroup":"Drivers who misused the system","action":"Drivers misusing the Autopilot system","consequence":"Fatal crashes"}},{"i":"R2940","hd":"Prepare to get manipulated by emotionally expressive chatbots","pd":"2024-04-15","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.5  Human computer interaction harm"],"t":"Prepare to get manipulated by emotionally expressive chatbots","s":"The emotional mimicry of OpenAI’s new version of ChatGPT could lead AI assistants in some strange—even dangerous—directions. It’s nothing new for computers to mimic human social etiquette, emotion, or humor. We just aren’t used to them doing it very well. OpenAI’s presentation of an all-new version of ChatGPT on Monday suggests that’s about to change. It’s built around an updated AI model called GPT-4o , which OpenAI says is better able to make sense of visual and auditory input, describing it as “multimodal.” You can point your phone at something, like a broken coffee cup or differential equation, and ask ChatGPT to suggest what to do.","u":"https://www.wired.com/story/prepare-to-get-manipulated-by-emotionally-expressive-chatbots/","d":"2024-04-15","e":"Chronic","x":{"occurrenceStatus":"probable","publicationDate":"2024-04-15","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-04-15","organization":"OpenAI","aiSystem":"ChatGPT (OpenAI)","affectedGroup":"Users of ChatGPT","action":"Generated emotionally expressive responses","consequence":"Potential misuse and manipulation"}},{"i":"R2941","hd":"Artificial intelligence lgbtq representation openai sora","pd":"2024-04-02","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.1  Representational harm"],"t":"Artificial intelligence lgbtq representation openai sora","s":"WIRED investigates how artificial intelligence tools, like OpenAI’s Sora, currently portray members of the LGBTQ community. Hint: It’s a lot of purple hair. Yes, San Francisco is a nexus of artificial intelligence innovation, but it’s also one of the queerest cities in America. The Mission District, where ChatGPT maker OpenAI is headquartered, butts up against the Castro, where sidewalk crossings are coated with rainbows, and older nude men are often seen milling about. And queer people are joining the AI revolution “So many people in this field are gay men, which is something I think few people talk about,” says Spencer Kaplan, an anthropologist and PhD student at Yale who moved to San Francisco to study the developers building generative tools.","u":"https://www.wired.com/story/artificial-intelligence-lgbtq-representation-openai-sora/","d":"2024-04-02","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2024-04-02","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-04-02","organization":"OpenAI","aiSystem":"Generative AI","affectedGroup":"LGBTQ+ individuals","action":"Generated content","consequence":"Exposure to biased representation"}},{"i":"R2943","hd":"AI altered hitler speech viral","pd":"2024-03-11","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.3  Misinformation / information hazard harm"],"t":"Ai altered hitler speech viral","s":"Two AI-altered clips of Hitler’s 1939 Reichstag speech have racked up millions of views on X after being shared by a far-right troll. AI-altered video clips of Adolf Hitler’s 1939 Reichstag speech at the beginning of World War II have recently gone viral. In the speech, Hitler proclaimed that the upcoming war would bring about the “annihilation of the Jewish race in Europe.” While Hitler did say this, the speech in the video clips was translated from German to English. The videos, which feature text that makes it clear the speech was an AI audio translation, have been viewed more than 15 million times, according to X. The two videos were first shared on Thursday by a hugely influential far-right conspiracy influencer known as Dom Lucre on X, who has previously shared child exploitation imagery.","u":"https://www.wired.com/story/ai-altered-hitler-speech-viral/","d":"2024-03-11","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2024-03-11","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-03-11","organization":"Far-right conspiracy influencer Dom Lucre","aiSystem":"AI-altered video clips","affectedGroup":"General public","action":"Shared AI-altered video clips of Hitler's speech","consequence":"Exposure to misleading content"}},{"i":"R2944","hd":"Google deepfake porn dmca takedowns","pd":"2024-03-11","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.4  Malicious use harm"],"t":"Google deepfake porn dmca takedowns","s":"Content creators are using copyright laws to get nonconsensual deepfakes removed from the web. With the complaints covering nearly 30,000 URLs, experts say Google should do more to help. The number of nonconsensual deepfake porn videos online has exploded since 2017. As the harmful videos have spread, thousands of women—including Twitch streamers, gamers, and other content creators—have complained to Google about websites hosting the videos and tried to get the tech giant to remove them from its search results. A WIRED analysis of copyright claims regarding websites that host deepfake porn videos reveals that thousands of takedown requests have been made, with the frequency of complaints increasing.","u":"https://www.wired.com/story/google-deepfake-porn-dmca-takedowns/","d":"2024-03-11","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2024-03-11","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-03-11","organization":"Google","aiSystem":"Deepfake technology","affectedGroup":"Women, content creators","action":"Removed nonconsensual deepfake porn videos from search results","consequence":"Exposure to harmful content, loss of income and reputation"}},{"i":"R2945","hd":"Google timnit gebru AI what really happened","pd":"2024-03-11","k":"United States of America","p":"United States of America","b":["Labor"],"h":["3.3  Employment displacement / quality harm"],"t":"Google timnit gebru ai what really happened","s":"She was a star engineer who warned that messy AI can spread racism. Google brought her in. Then it forced her out. Can Big Tech take criticism from within? One afternoon in late November of last year, Timnit Gebru was sitting on the couch in her San Francisco Bay Area home, crying. Gebru, a researcher at Google , had just clicked out of a last-minute video meeting with an executive named Megan Kacholia, who had issued a jarring command. Gebru was the coleader of a group at the company that studies the social and ethical ramifications of artificial intelligence , and Kacholia had ordered Gebru to retract her latest research paper—or else remove her name from its list of authors, along with those of several other members of her team.","u":"https://www.wired.com/story/google-timnit-gebru-ai-what-really-happened/","d":"2024-03-11","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2024-03-11","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2023-11","organization":"Google","aiSystem":"Not specified in report","affectedGroup":"Timnit Gebru","action":"Was forced to retract her research paper or remove her name from the author list","consequence":"Was terminated from her position at Google"}},{"i":"R2946","hd":"Florida teens arrested deepfake nudes classmates","pd":"2024-03-08","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.4  Malicious use harm"],"t":"Florida teens arrested deepfake nudes classmates","s":"In what appears to be the first criminal case of its kind, two teenage boys were charged under a 2022 Florida law for allegedly creating AI-generated images depicting middle school classmates. Two teenage boys from Miami, Florida, were arrested in December for allegedly creating and sharing AI-generated nude images of male and female classmates without consent, according to police reports obtained by WIRED via public record request. The arrest reports say the boys, aged 13 and 14, created the images of the students who were “between the ages of 12 and 13.” The Florida case appears to be the first arrests and criminal charges as a result of alleged sharing of AI-generated nude images to come to light.","u":"https://www.wired.com/story/florida-teens-arrested-deepfake-nudes-classmates/","d":"2024-03-08","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2024-03-08","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"December","organization":"Miami Police Department and Florida authorities","aiSystem":"AI-generated deepfake technology","affectedGroup":"Middle school students","action":"Created and shared AI-generated nude images without consent","consequence":"Arrest and criminal charges"}},{"i":"R2947","hd":"Robert f kennedy jr chatbot microsoft openai disappeared","pd":"2024-03-04","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.3  Misinformation / information hazard harm"],"t":"Robert f kennedy jr chatbot microsoft openai disappeared","s":"The RFK Jr. campaign’s chatbot had previously affirmed Kennedy’s promotion of conspiracy theories, and appeared to circumvent OpenAI’s ban on political use. Since Robert F. Kennedy Jr. first announced his longshot presidential bid, his campaign has leaned into a variety of unorthodox digital strategies He’s appeared on countless podcasts and collaborated with popular influencers to reach voters online. More recently, the Kennedy campaign has experimented with an AI chatbot that used an apparent loophole to get around OpenAI’s restrictions on political use. On Sunday, after inquiries from WIRED, the chatbot disappeared.","u":"https://www.wired.com/story/robert-f-kennedy-jr-chatbot-microsoft-openai-disappeared/","d":"2024-03-04","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2024-03-04","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-03-04","organization":"Robert F. Kennedy Jr. campaign","aiSystem":"AI chatbot","affectedGroup":"People seeking information or engaging with the chatbot","action":"Used an apparent loophole to get around OpenAI's restrictions on political use","consequence":"Chatbot disappeared"}},{"i":"R2952","hd":"Meta crack down AI generated fakes","pd":"2024-02-06","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.3  Misinformation / information hazard harm"],"t":"Meta crack down ai generated fakes","s":"Some AI-generated images posted to Facebook, Instagram, and Threads will in future be labeled as artificial. But only if they are made using tools from companies willing to work with Meta. Meta, like other leading tech companies, has spent the past year promising to speed up deployment of generative artificial intelligence. Today it acknowledged it must also respond to the technology’s hazards, announcing an expanded policy of tagging AI-generated images posted to Facebook, Instagram, and Threads with warning labels to inform people of their artificial origins. Yet much of the synthetic media likely to appear on Meta’s platforms is unlikely to be covered by the new policy, leaving many gaps through which malicious actors could slip.","u":"https://www.wired.com/story/meta-crack-down-ai-generated-fakes/","d":"2024-02-06","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2024-02-06","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-02-06","organization":"Meta (Facebook, Instagram, Threads)","aiSystem":"Generative AI","affectedGroup":"People viewing AI-generated images on Meta platforms","action":"AI-generated images are labeled with warning labels","consequence":"Misleading exposure to AI-generated content"}},{"i":"R2953","hd":"Hulu anti hamas ad generative AI","pd":"2024-01-30","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.3  Misinformation / information hazard harm"],"t":"Hulu anti hamas ad generative ai","s":"The ad, which appears to be made using generative AI, shows how the technology can be used not just to mislead, but to more subtly influence. Hulu ran an anti-Hamas ad that appears to be made using artificial intelligence to show an idealized version of Gaza—claiming this paradise destination could exist if not for Hamas. The 30-second spot, opening like a tourism ad, shows palm trees and coastlines. There are five-star hotels and children playing. People dance, eat, and laugh, while a voiceover encourages visitors to “experience a culture rich in tradition.” But it suddenly shifts, turning the face of a smiling man into a grimacing one.","u":"https://www.wired.com/story/hulu-anti-hamas-ad-generative-ai/","d":"2024-01-30","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2024-01-30","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-01-30","organization":"Hulu","aiSystem":"Generative AI","affectedGroup":"Potential tourists","action":"Generated and displayed promotional content","consequence":"Misled potential tourists"}},{"i":"R2954","hd":"Doj predictive policing lawmakers demand","pd":"2024-01-29","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.2  Surveillance harm"],"t":"Doj predictive policing lawmakers demand","s":"Members of Congress say the DOJ is funding the use of AI tools that further discriminatory policing practices. They're demanding higher standards for federal grants. The United States Department of Justice has failed to convince a group of US lawmakers that state and local police agencies aren't awarded federal grants to buy AI-based “policing” tools known to be inaccurate, if not prone to exacerbating biases long observed in US police forces. Seven members of Congress wrote in a letter to the DOJ , first obtained by WIRED, that the information they pried loose from the agency had only served to inflame their concerns about the DOJ’s police grant program.","u":"https://www.wired.com/story/doj-predictive-policing-lawmakers-demand/","d":"2024-01-29","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2024-01-29","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-01-29","organization":"United States Department of Justice","aiSystem":"AI-based ‘policing’ tools","affectedGroup":"state and local police agencies","action":"award federal grants","consequence":"further discriminatory policing practices"}},{"i":"R2955","hd":"George carlin AI standup written by humans","pd":"2024-01-29","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.3  Data rights / consent violation"],"t":"George carlin ai standup written by humans","s":"A lawsuit filed by George Carlin’s manager will still move forward. The estate of George Carlin has filed a federal lawsuit against the comedy podcast Dudesy for an hour-long comedy special sold as an AI-generated impression of the late comedian. But a representative for one of the podcast hosts behind the special now admits that it was actually written by a human. In the lawsuit , filed by Carlin manager Jerold Hamza in a California district court, the Carlin estate points out that the special, “ George Carlin: I'm Glad I'm Dead ” (which was set to “private” on YouTube shortly after the lawsuit was filed), presents itself as being created by an AI trained on decades' worth of Carlin's material.","u":"https://www.wired.com/story/george-carlin-ai-standup-written-by-humans/","d":"2024-01-29","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2024-01-29","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-01-29","organization":"Dudesy (comedy podcast)","aiSystem":"AI-generated impression of George Carlin","affectedGroup":"George Carlin's estate","action":"Presenting the comedy special as AI-generated","consequence":"Misleading presentation to the public"}},{"i":"R2956","hd":"Taylor swift deepfake porn artificial intelligence pushback","pd":"2024-01-26","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.4  Malicious use harm"],"t":"Taylor swift deepfake porn artificial intelligence pushback","s":"Deepfake porn is prolific. The explicit, AI-generated images of Taylor Swift that circulated on X this week are taking the issue to new heights. If anyone can rally up a base, it’s Taylor Swift When sexually explicit, likely AI-generated, fake images of Swift circulated on social media this week, it galvanized her fans. Swifties found phrases and hashtags related to the images and flooded them with videos and photos of Swift performing. “Protect Taylor Swift” went viral, trending as Swifties spoke out against not just the Swift deepfakes, but all nonconsensual, explicit images made of women. Swift, arguably the most famous woman in the world right now, has become the high-profile victim of an all-too-frequent form of harassment.","u":"https://www.wired.com/story/taylor-swift-deepfake-porn-artificial-intelligence-pushback/","d":"2024-01-26","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2024-01-26","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-01-26","organization":"Taylor Swift and her fans","aiSystem":"AI-generated deepfake technology","affectedGroup":"Taylor Swift","action":"AI-generated deepfake images of Taylor Swift","consequence":"Increased public attention and backlash"}},{"i":"R2957","hd":"Biden robocall deepfake danger","pd":"2024-01-23","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.3  Misinformation / information hazard harm"],"t":"Biden robocall deepfake danger","s":"An uncanny audio deepfake impersonating President Biden has sparked further fears from lawmakers and experts about generative AI’s role in spreading disinformation. A deepfake robocall impersonating President Biden is rocking the New Hampshire primary, and no one knows who’s behind it. Over the weekend, voters in New Hampshire and New England received a call from a voice that sounded eerily like Biden, touting election “malarkey” and discouraging them to vote in the Tuesday primaries. “We know the value of voting Democratic,” the robocall says. “It’s important that you save your vote for the November election. We’ll need your help electing Democrats up and down the ticket.","u":"https://www.wired.com/story/biden-robocall-deepfake-danger/","d":"2024-01-23","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2024-01-23","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-01-23","organization":"Not specified in report","aiSystem":"Generative AI","affectedGroup":"Voters in New Hampshire and New England","action":"Generated and disseminated a deepfake robocall impersonating President Biden","consequence":"Spreading disinformation and influencing voter behavior"}},{"i":"R2960","hd":"Hollywood saved your job from AI 2023 will it last","pd":"2023-12-25","k":"United States of America","p":"United States of America","b":["Labor"],"h":["3.3  Employment displacement / quality harm"],"t":"Hollywood saved your job from ai 2023 will it last","s":"The year was dominated by talk of what artificial intelligence could do—and what it could do better than most humans. Revolt against the machines began at Swingers. And at Bob’s Big Boy, where for weeks Drew Carey picked up the tab Members of the Writers Guild of America, or WGA, met at both Los Angeles-area diners frequently during their 148-day strike , which hinged on protecting Hollywood’s scribes from being overrun by the march of artificial intelligence Members of the WGA were just a small part of the resistance. There were others. The Screen Actors Guild—American Federation of Television and Radio Artists, or SAG-AFTRA, soon joined them on the picket lines, together forming a formidable uprising against the perceived threat of AI.","u":"https://www.wired.com/story/hollywood-saved-your-job-from-ai-2023-will-it-last/","d":"2023-12-25","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2023-12-25","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2023-12-25","organization":"Screen Actors Guild—American Federation of Television and Radio Artists (SAG-AFTRA)","aiSystem":"Artificial intelligence","affectedGroup":"Members of the Screen Actors Guild—American Federation of Television and Radio Artists (SAG-AFTRA)","action":"joined the picket lines","consequence":"formidable uprising against the perceived threat of AI"}},{"i":"R2962","hd":"Platform work EU overhauls","pd":"2023-12-13","k":"United States of America","p":"United States of America","b":["Labor"],"h":["3.2  Algorithmic management harm"],"t":"Platform work eu overhauls","s":"Platforms will no longer be able to fire their workers automatically as part of new EU rules that will affect millions of people, including Uber drivers and Deliveroo couriers. Platform workers can no longer be fired automatically by algorithms, according to new European Union rules agreed today in a sweeping reform of the gig economy that will affect Uber drivers and Deliveroo couriers. “Now we have a proper system, which is something that doesn't exist anywhere else around the world,” said Elisabetta Gualmini, an Italian politician who led the negotiations for the European Parliament in a press conference on Wednesday.","u":"https://www.wired.com/story/platform-work-eu-overhauls/","d":"2023-12-13","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2023-12-13","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2023-12-13","organization":"Platform companies (e.g., Uber, Deliveroo)","aiSystem":"Automated hiring algorithm","affectedGroup":"Platform workers (e.g., Uber drivers, Deliveroo couriers)","action":"Automatically terminated employment","consequence":"Loss of employment"}},{"i":"R2963","hd":"Oversight board meta israel hamas","pd":"2023-12-07","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.2  Allocative harm"],"t":"Oversight board meta israel hamas","s":"The board is going to look at two posts removed for violating Meta’s policies against sharing graphic imagery and depicting dangerous organizations and individuals. Today, Meta’s Oversight Board announced it would take on two expedited cases, the first ever, both dealing with the ongoing conflict between Israel and Hamas. The case will look at two posts that were initially removed from and then reinstated on Instagram and Facebook for violating Meta’s policies against sharing graphic imagery and depicting dangerous organizations and individuals, respectively. One of the posts showed the aftermath of the attack on Al-Shifa Hospital by the Israel Defense Forces, and the other was a video of an Israeli hostage being taken by Hamas on October 7.","u":"https://www.wired.com/story/oversight-board-meta-israel-hamas/","d":"2023-12-07","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2023-12-07","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2023-12-07","organization":"Meta (Facebook and Instagram)","aiSystem":"Meta's content moderation system","affectedGroup":"People who posted content related to the conflict","action":"Posts were initially removed and then reinstated due to policy violations","consequence":"Content was removed and later restored, causing confusion and potential misinformation"}},{"i":"R2964","hd":"Inside americas school internet censorship machine","pd":"2023-12-04","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.2  Allocative harm"],"t":"Inside americas school internet censorship machine","s":"A WIRED investigation into internet censorship in US schools found widespread use of filters to censor health, identity, and other crucial information. Students say it makes the web entirely unusable. Around dinner time one night in May, a student in Albuquerque, New Mexico, Googled “Obergefell v. Hodges ruling.” But instead of a list of links to information about the landmark US Supreme Court case that legalized same-sex marriage, the 11th grader from La Cueva High School was redirected to a gray screen with Albuquerque Public Schools’ logo and the message: “Restricted. This website has been blocked by your administrator.”","u":"https://www.wired.com/story/inside-americas-school-internet-censorship-machine/","d":"2023-12-04","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2023-12-04","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"May","organization":"Albuquerque Public Schools","aiSystem":"Internet filtering systems","affectedGroup":"Students, particularly those in La Cueva High School","action":"Blocked websites containing sensitive information","consequence":"Restriction of access to crucial information, including legal rulings"}},{"i":"R2965","hd":"Chatgpt poem forever security roundup","pd":"2023-12-02","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.1  Privacy violation"],"t":"Chatgpt poem forever security roundup","s":"Plus: A major ransomware crackdown, the arrest of Ukraine's cybersecurity chief, and a hack-for-hire entrepreneur charged with attempted murder. Brinkmanship escalated in the US Congress this week over strategies to reauthorize the government surveillance powers known as “Section 702,” as civil rights groups sounded the alarm about the consequences of the program and its potential renewal. A WIRED investigation of more than 100 restricted Telegram channels indicated that the communication app's bans on extremist discourse aren't effective or adequate bans. And the identity management platform Okta admitted this week that a security breach previously thought to impact 1 percent of its customers actually affected 100 percent.","u":"https://www.wired.com/story/chatgpt-poem-forever-security-roundup/","d":"2023-12-02","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2023-12-02","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2023-12-02","organization":"Okta","aiSystem":"Not specified in report","affectedGroup":"Customers of Okta","action":"Admitted to a security breach","consequence":"Affected 100% of customers"}},{"i":"R2966","hd":"Social media AI dead bodies","pd":"2023-11-15","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.1  Privacy violation"],"t":"Social media ai dead bodies","s":"Poverty, fentanyl, and lack of public funding mean morgues are overloaded with unidentified bodies. TikTok and Facebook pages are filling the gap—with AI proving a powerful and controversial new tool. Content Warning: This story includes references to suicide. If you need help, call the Suicide and Crisis Lifeline for your region. In 2021, an unidentified Black woman died by suicide after jumping off the Brooklyn Bridge. She was wearing hot-pink nail polish, and had a pink left eyebrow piercing and several tattoos—all distinguishing features that should have made it easier to identify her. Two years later, her identity is still unknown.","u":"https://www.wired.com/story/social-media-ai-dead-bodies/","d":"2023-11-15","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2023-11-15","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2021","organization":"Social media platforms (TikTok and Facebook)","aiSystem":"AI-powered identification tools","affectedGroup":"Unidentified deceased individuals","action":"Used AI to generate identifying features","consequence":"Increased privacy risks for unidentified deceased"}},{"i":"R2968","hd":"Johnny cash artificial intelligence taylor swift barbie girl covers music future","pd":"2023-11-06","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.3  Data rights / consent violation"],"t":"Johnny cash artificial intelligence taylor swift barbie girl covers music future","s":"With covers of “Blank Space” and Aqua's “Barbie Girl” going viral, Johnny Cash is suddenly the voice of AI. The choice is telling. When Texas-based copywriter Dustin Ballard released a cover of Aqua’s 1997 Europop hit “Barbie Girl” this summer using an AI-generated version of Johnny Cash’s voice, he was surprised by its reception. “I actually expected more of a backlash,” he says. Earlier this fall, when he followed up with AI Johnny Cash singing Taylor Swift ’s “Blank Space,” the feedback was unexpectedly positive once again. “This is hauntingly beautiful,” the top comment reads. Media coverage skewed glowing. “It absolutely slaps,” Futurism wrote.","u":"https://www.wired.com/story/johnny-cash-artificial-intelligence-taylor-swift-barbie-girl-covers-music-future/","d":"2023-11-06","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2023-11-06","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2023-11-06","organization":"Dustin Ballard (copywriter)","aiSystem":"AI-generated voice synthesis technology","affectedGroup":"Johnny Cash's voice","action":"AI-generated voice synthesizing Johnny Cash's voice","consequence":"Unexpected positive reception and media coverage"}},{"i":"R2970","hd":"Amazons AI van inspections powerful data feed","pd":"2023-10-24","k":"United States of America","p":"United States of America","b":["Labor"],"h":["3.2  Algorithmic management harm"],"t":"Amazons ai van inspections powerful data feed","s":"Amazon delivery drivers at hundreds of sites around the world will be asked to drive through camera-studded archways that log every dent, scratch, or damaged tire. Amazon is splashing out on new vehicle inspectors to watch for damage or wear to its vast fleet of delivery vans—and they’re not human. The retailer is installing camera-studded inspection stations equipped with artificial intelligence-powered technology called AVI, or automated vehicle inspection, at hundreds of its distribution centers worldwide. When a driver working out of any of the 20 delivery centers currently equipped with the tech returns their vehicle at the end of a shift, they slowly drive it through a sensor-laden archway made by startup UVeye, which has headquarters in the US and Israel.","u":"https://www.wired.com/story/amazons-ai-van-inspections-powerful-data-feed/","d":"2023-10-24","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2023-10-24","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2023-10-24","organization":"Amazon","aiSystem":"Automated Vehicle Inspection (AVI) system","affectedGroup":"Amazon delivery drivers","action":"Slowly drive their vehicle through a sensor-laden archway equipped with AI technology","consequence":"Their vehicles are inspected for damage or wear by an AI-powered system"}},{"i":"R2971","hd":"Cruise robotaxi self driving permit revoked california","pd":"2023-10-24","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.7  Physical safety harm"],"t":"Cruise robotaxi self driving permit revoked california","s":"The California DMV says the company’s autonomous taxis are “not safe” and that Cruise “misrepresented” safety information about its self-driving vehicle technology. California has suspended driverless vehicles operated by the General Motors subsidiary Cruise in the city of San Francisco—just two months after the state began allowing the robotaxis to pick up paying passengers around the clock. The suspension stems from a gruesome incident on October 2 in which a human-driven vehicle hit a female pedestrian and threw her into the path of a Cruise car. The driverless Cruise car hit her, stopped, and then tried to pull over, dragging her approximately 20 feet.","u":"https://www.wired.com/story/cruise-robotaxi-self-driving-permit-revoked-california/","d":"2023-10-24","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2023-10-24","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2023-10-02","organization":"General Motors subsidiary Cruise","aiSystem":"self-driving vehicle technology","affectedGroup":"female pedestrian","action":"hit a female pedestrian and threw her into the path of a Cruise car","consequence":"dragged her approximately 20 feet"}},{"i":"R2976","hd":"Soundthinking geolitica acquisition predictive policing","pd":"2023-09-27","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.2  Surveillance harm"],"t":"Soundthinking geolitica acquisition predictive policing","s":"SoundThinking is purchasing parts of Geolitica, the company that created PredPol. Experts say the acquisition marks a new era of companies dictating how police operate. SoundThinking, the company behind the gunshot-detection system ShotSpotter, is quietly acquiring staff, patents, and customers of the firm that created the notorious predictive policing software PredPol, WIRED has learned. In an August earnings call, SoundThinking CEO Ralph Clark announced to investors that the company was negotiating an agreement to acquire parts of Geolitica—formerly called PredPol—and transition its customers to SoundThinking’s own “patrol management” solution.","u":"https://www.wired.com/story/soundthinking-geolitica-acquisition-predictive-policing/","d":"2023-09-27","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2023-09-27","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2023-09-27","organization":"SoundThinking","aiSystem":"Predictive policing algorithm","affectedGroup":"Job applicants","action":"Transitioned customers to SoundThinking's patrol management solution","consequence":"Created unequal outcomes for applicants"}},{"i":"R2977","hd":"FBI agents face recognition without proper training","pd":"2023-09-25","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.2  Surveillance harm"],"t":"Fbi agents face recognition without proper training","s":"The FBI makes heavy use of face recognition services like that of controversial startup Clearview AI, but 95 percent of the agents using them haven’t completed training on the technology. The US Federal Bureau of Investigation (FBI) has done tens of thousands of face recognition searches using software from outside providers in recent years. Yet only 5 percent of the 200 agents with access to the technology have taken the bureau’s three-day training course on how to use it, a report from the Government Accountability Office (GAO) this month reveals. The bureau has no policy for face recognition use in place to protect privacy, civil rights, or civil liberties.","u":"https://www.wired.com/story/fbi-agents-face-recognition-without-proper-training/","d":"2023-09-25","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2023-09-25","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2023-09-25","organization":"US Federal Bureau of Investigation (FBI)","aiSystem":"face recognition technology","affectedGroup":"agents with access to the technology","action":"performed face recognition searches","consequence":"lack of proper training and privacy protection policies"}},{"i":"R2979","hd":"Local governments generative AI","pd":"2023-09-11","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.6  Quality of service harm"],"t":"Local governments generative ai","s":"State and local governments in the US are scrambling to harness tools like ChatGPT to unburden their bureaucracies, rushing to write their own rules—and avoid generative AI's many pitfalls. The United States Environmental Protection Agency blocked its employees from accessing ChatGPT while the US State Department staff in Guinea used it to draft speeches and social media posts. Maine banned its executive branch employees from using generative artificial intelligence for the rest of the year out of concern for the state’s cybersecurity. In nearby Vermont, government workers are using it to learn new programming languages and write internal-facing code, according to Josiah Raiche, the state’s director of artificial intelligence.","u":"https://www.wired.com/story/local-governments-generative-ai/","d":"2023-09-11","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2023-09-11","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2023-09-11","organization":"State and local governments in the United States","aiSystem":"Generative AI systems like ChatGPT","affectedGroup":"Government employees","action":"Using generative AI systems for various tasks","consequence":"Potential exposure to cybersecurity risks and privacy issues"}},{"i":"R2980","hd":"Your new car privacy nightmare","pd":"2023-09-09","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.1  Privacy violation"],"t":"Your new car privacy nightmare","s":"Plus: Apple patches newly discovered flaws exploited by NSO Group spyware, North Korean hackers target security researchers, and more. Last week, WIRED published a deep-dive investigation into Trickbot , the prolific Russian ransomware gang. This week, US and UK authorities sanctioned 11 alleged members of Trickbot and its related group, Conti , including Maksim Galochkin, aka Bentley, one of the alleged members whose real-world identity we confirmed through our investigation. Coincidence? Maybe. Either way, it's a big deal. In addition to the US and UK sanctions, the US Justice Department also unsealed indictments filed in three US federal courts against Galochkin and eight other alleged Trickbot members for ransomware attacks against entities in Ohio, Tennessee, and California.","u":"https://www.wired.com/story/your-new-car-privacy-nightmare/","d":"2023-09-09","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2023-09-09","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2023-09-09","organization":"US and UK authorities, US Justice Department","aiSystem":"Not specified in report","affectedGroup":"Entities in Ohio, Tennessee, and California","action":"Sanctioned and indicted for ransomware attacks","consequence":"Potential exposure to cyber threats and surveillance"}},{"i":"R2981","hd":"Axon taser drones ethics board","pd":"2023-09-08","k":"United States of America","p":"United States of America","b":["Deployment Context / Weapons"],"h":["5.1  Autonomous weapons / lethal targeting harm"],"t":"Axon taser drones ethics board","s":"The CEO’s vision for Taser-equipped drones includes a fictitious scenario in which the technology averts a shooting at a day care center. This article was copublished with The Markup, a nonprofit, investigative newsroom that challenges technology to serve the public good. Sign up for its newsletters here Less than 10 days after the Robb Elementary School shooting in Uvalde, Texas, in May 2022, Axon Enterprises CEO Rick Smith announced the company had formally started developing Taser-equipped drones. The technology, Smith argued, could potentially save lives during mass shootings by incapacitating active shooters within seconds.","u":"https://www.wired.com/story/axon-taser-drones-ethics-board/","d":"2023-09-08","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2023-09-08","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"Less than 10 days after the Robb Elementary School shooting in Uvalde, Texas, in May 2022","organization":"Axon Enterprises","aiSystem":"Taser-equipped drones","affectedGroup":"Active shooters","action":"Used to incapacitate active shooters","consequence":"Potential wrongful death"}},{"i":"R2984","hd":"Ubers fatal self driving car crash saga over operator avoids prison","pd":"2023-07-29","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.7  Physical safety harm"],"t":"Ubers fatal self driving car crash saga over operator avoids prison","s":"After five years of purgatory, Rafaela Vasquez, the operator of a self-driving Uber that killed a pedestrian in 2018, pleaded guilty to endangerment. It’s been more than five years since an Uber self-driving car struck and killed a woman named Elaine Herzberg as she walked her bicycle across a road in Tempe, Arizona. Herzberg’s death instantly turned what had been a philosophical conundrum into a glaringly real, legal one: Who gets blamed for a road fatality in the awkward, liminal era of self-driving cars, when humans are essentially babysitters of imperfect, still-learning AI systems? Is it the company with the erring car?","u":"https://www.wired.com/story/ubers-fatal-self-driving-car-crash-saga-over-operator-avoids-prison/","d":"2023-07-29","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2023-07-29","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2018-10-03","organization":"Uber","aiSystem":"self-driving Uber car","affectedGroup":"Elaine Herzberg","action":"struck and killed a pedestrian","consequence":"instantly turned into a legal issue"}},{"i":"R2990","hd":"Chatgpt prompt injection attack security","pd":"2023-05-25","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.4  Malicious use harm"],"t":"Chatgpt prompt injection attack security","s":"Indirect prompt-injection attacks can leave people vulnerable to scams and data theft when they use the AI chatbots. Sydney is back. Sort of. When Microsoft shut down the chaotic alter ego of its Bing chatbot , fans of the dark Sydney personality mourned its loss But one website has resurrected a version of the chatbot—and the peculiar behavior that comes with it. Bring Sydney Back was created by Cristiano Giardina, an entrepreneur who has been experimenting with ways to make generative AI tools do unexpected things. The site puts Sydney inside Microsoft’s Edge browser and demonstrates how generative AI systems can be manipulated by external inputs.","u":"https://www.wired.com/story/chatgpt-prompt-injection-attack-security/","d":"2023-05-25","e":"Acute","x":{"occurrenceStatus":"probable","publicationDate":"2023-05-25","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2023-05-25","organization":"Microsoft","aiSystem":"Generative AI chatbot","affectedGroup":"Individuals using Microsoft Edge browser","action":"Manipulate generative AI systems with external inputs","consequence":"Vulnerability to scams and data theft"}},{"i":"R2991","hd":"Content moderation language artificial intelligence","pd":"2023-05-23","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.2  Allocative harm"],"t":"Content moderation language artificial intelligence","s":"Social media companies claim new language models can remove harmful content in every language. But those systems’ shortcomings can have vast consequences. Three parts Bosnian text. Thirteen parts Kurdish. Fifty-five parts Swahili. Eleven thousand parts English. This is part of the data recipe for Facebook’s new large language model, which the company claims is able to detect and rein in harmful content in over 100 languages. Bumble uses similar technology to detect rude and unwanted messages in at least 15 languages. Google uses it for everything from translation to filtering newspaper comment sections. All have comparable recipes and the same dominant ingredient: English-language data.","u":"https://www.wired.com/story/content-moderation-language-artificial-intelligence/","d":"2023-05-23","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2023-05-23","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2023-05-23","organization":"Facebook, Bumble, Google","aiSystem":"Large language model","affectedGroup":"People posting content in various languages","action":"Used to detect and remove harmful content","consequence":"Vast consequences including potential misuse of English-language data"}},{"i":"R2992","hd":"Cnet published AI generated stories then its staff pushed back","pd":"2023-05-16","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.3  Misinformation / information hazard harm"],"t":"Cnet published ai generated stories then its staff pushed back","s":"Like Hollywood's striking screenwriters, the outlet's employees want protections against potentially job-killing automation. In November, venerable tech outlet CNET began publishing articles generated by artificial intelligence, on topics such as personal finance, that proved to be riddled with errors Today the human members of its editorial staff have unionized, calling on their bosses to provide better conditions for workers and more transparency and accountability around the use of AI. “In this time of instability, our diverse content teams need industry-standard job protections, fair compensation, editorial independence, and a voice in the decisionmaking process, especially as automated technology threatens our jobs and reputations,” reads the mission statement of the CNET Media Workers Union, whose more than 100 members include writers, editors, video producers, and other content…","u":"https://www.wired.com/story/cnet-published-ai-generated-stories-then-its-staff-pushed-back/","d":"2023-05-16","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2023-05-16","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2023-05-16","organization":"CNET","aiSystem":"AI-generated stories","affectedGroup":"human members of its editorial staff","action":"published articles generated by artificial intelligence","consequence":"called on their bosses to provide better conditions for workers and more transparency and accountability"}},{"i":"R2993","hd":"Unfair automated hiring systems are everywhere FTC","pd":"2023-05-15","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.2  Allocative harm"],"t":"Unfair automated hiring systems are everywhere ftc","s":"Algorithms can exacerbate employment discrimination. It's time for the US Federal Trade Commission to regulate them. Earlier this month, Lina Khan, chair of the US Federal Trade Commission (FTC), wrote an essay in The New York Times affirming the agency’s commitment to regulating AI. But there was one AI application Khan didn’t mention that the FTC urgently needs to regulate: automated hiring systems. These range in complexity from tools that merely parse resumes and rank them to systems that green-light candidates and trash applicants deemed unfit. Increasingly, working Americans are obligated to use them if they want to get hired.","u":"https://www.wired.com/story/unfair-automated-hiring-systems-are-everywhere-ftc/","d":"2023-05-15","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2023-05-15","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2023-05-15","organization":"US Federal Trade Commission (FTC)","aiSystem":"Automated hiring algorithms","affectedGroup":"Job applicants","action":"Rank job applicants","consequence":"Created unequal outcomes for applicants"}},{"i":"R2994","hd":"Safegraph US air force location data","pd":"2023-05-08","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.2  Surveillance harm"],"t":"Safegraph us air force location data","s":"Documents obtained by WIRED show SafeGraph, which sold location data related to Planned Parenthood visits, is now pursuing contracts with the US Air Force. The data broker made famous for selling location data related to abortion clinic visits has signed a contract with the US Air Force and plans to provide information about “sensitive places” and “adversary state-owned enterprises” around the world, according to records obtained by WIRED. The company, SafeGraph, told the military that its data can be used for “analyzing human activity for landing zone selection,” as well as to identify hospitals, schools, and houses of worship to “help avoid collateral damage.”","u":"https://www.wired.com/story/safegraph-us-air-force-location-data/","d":"2023-05-08","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2023-05-08","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2023-05-08","organization":"SafeGraph","aiSystem":"SafeGraph's location data","affectedGroup":"People visiting sensitive places and adversary state-owned enterprises around the world","action":"Providing location data for analysis and identification of critical infrastructure","consequence":"Potential misuse for military purposes leading to surveillance and targeting of civilians"}},{"i":"R2995","hd":"ICE agent database abuse records","pd":"2023-04-17","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.2  Surveillance harm"],"t":"Ice agent database abuse records","s":"Documents obtained by WIRED detail hundreds of investigations by the US agency into alleged database misuse that includes harassment, stalking, and more. Since 2016, hundreds of US Immigration and Customs Enforcement employees and contractors have faced internal investigations into abuse of confidential law enforcement databases and agency computers. The alleged misconduct includes a swath of unlawful behavior, from stalking and harassment to passing information to criminals. ICE says these databases are vital tools for enforcing the law. However, agency records of internal misconduct investigations reveal that they can also be used to subvert it.","u":"https://www.wired.com/story/ice-agent-database-abuse-records/","d":"2023-04-17","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2023-04-17","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2016-present","organization":"US Immigration and Customs Enforcement (ICE)","aiSystem":"Law enforcement databases","affectedGroup":"US Immigration and Customs Enforcement employees and contractors","action":"Internal investigations into abuse of confidential law enforcement databases and agency computers","consequence":"Subversion of law enforcement efforts"}},{"i":"R2997","hd":"Dashcam footage shows driverless cars cruise waymo clogging san francisco","pd":"2023-04-10","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.6  Quality of service harm"],"t":"Dashcam footage shows driverless cars cruise waymo clogging san francisco","s":"Videos obtained by WIRED from public transit vehicles reveal self-driving cars causing delays and potential danger to buses, trains, and passengers. The bus was stuck. San Francisco’s eastbound 54 Felton line was heading up a narrow residential street when a white SUV coming the other way stopped in the middle of the road. It was a rainy Sunday evening last month, and the bus driver leaned up to the windshield and peered through the haze at the SUV’s pulsing hazard lights before slumping back and exclaiming in surprise, \"What the hell? No driver of the car?!\" The 54, brought to a halt by an autonomous vehicle belonging to Alphabet’s Waymo, isn’t the only bus that’s run into trouble with San Francisco’s growing crowd of driverless vehicles.","u":"https://www.wired.com/story/dashcam-footage-shows-driverless-cars-cruise-waymo-clogging-san-francisco/","d":"2023-04-10","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2023-04-10","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2023-04-10","organization":"Alphabet's Waymo","aiSystem":"self-driving cars","affectedGroup":"San Francisco’s eastbound 54 Felton line","action":"blocked the bus","consequence":"causing delays and potential danger to buses, trains, and passengers"}},{"i":"R3003","hd":"Welfare fraud industry","pd":"2023-03-07","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.2  Allocative harm"],"t":"Welfare fraud industry","s":"When systems designed to catch welfare cheats go wrong, people find themselves trapped between secretive governments and even more opaque private companies. Mitch Daniels is a numbers guy, a cost-cutter. In the early 2000s, he tried and failed to rein in congressional spending under then-US president George W. Bush. So when he took office as Indiana governor in 2005, Daniels was ready to argue once again for fiscal discipline. He wanted to straighten out Indiana’s state government, which he deemed rife with dysfunction. And he started with its welfare system. “That department had been rocked by a series of criminal indictments, with cheats and caseworkers colluding to steal money meant for poor people,” he later said.","u":"https://www.wired.com/story/welfare-fraud-industry/","d":"2023-03-07","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2023-03-07","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2005","organization":"Indiana state government","aiSystem":"AI-powered welfare fraud detection system","affectedGroup":"welfare recipients","action":"used AI to identify and deny welfare benefits","consequence":"people found themselves trapped between secretive governments and private companies"}},{"i":"R3007","hd":"Algorithms allegedly penalized black renters the US government is watching","pd":"2023-01-21","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.2  Allocative harm"],"t":"Algorithms allegedly penalized black renters the us government is watching","s":"The Department of Justice warned a provider of tenant-screening software that its technology must comply with fair housing law. Two years ago, Mary Louis submitted an application to rent an apartment at Granada Highlands in Malden, Massachusetts. She liked that the unit had two full bathrooms and that there was a pool on the premises. But the landlord denied her the apartment, allegedly due to a score assigned to her by a tenant-screening algorithm made by SafeRent. Louis responded with references to prove 16 years of punctual rent payments, to no avail. Instead she took a different apartment that cost $200 more a month in an area with a higher crime rate.","u":"https://www.wired.com/story/algorithms-allegedly-penalized-black-renters-the-us-government-is-watching/","d":"2023-01-21","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2023-01-21","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2021","organization":"SafeRent","aiSystem":"tenant-screening algorithm","affectedGroup":"Black renters","action":"assigned a score to applicants","consequence":"denied rental applications"}},{"i":"R3010","hd":"San franciscos killer police robots threaten the citys most vulnerable","pd":"2022-12-01","k":"United States of America","p":"United States of America","b":["Deployment Context / Weapons"],"h":["5.1  Autonomous weapons / lethal targeting harm"],"t":"San franciscos killer police robots threaten the citys most vulnerable","s":"Law enforcement says that in some scenarios a lethal robot is the only way to protect public safety. Experts say the policy will harm communities of color. Three years ago, the San Francisco Board of Supervisors made history by becoming the first city in the nation to ban use of facial recognition technology by local government. Last night, the board went in a different direction, giving police the right to kill a criminal suspect with a teleoperated robot if they believe there is an imminent threat of death to police or members of the public. Assistant police chief David Lazar said ahead of the vote that killer robots might be needed in scenarios involving mass shootings or suicide bombers, citing the Mandalay Bay shooting in Las Vegas in 2017 and the killing of five police officers in Dallas, Texas, in 2016.","u":"https://www.wired.com/story/san-franciscos-killer-police-robots-threaten-the-citys-most-vulnerable/","d":"2022-12-01","e":"Acute","x":{"occurrenceStatus":"probable","publicationDate":"2022-12-01","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2022-12-01","organization":"San Francisco Police Department","aiSystem":"Teleoperated lethal robots","affectedGroup":"Criminal suspects","action":"Kill a criminal suspect with a teleoperated robot","consequence":"Exposure to lethal force"}},{"i":"R3012","hd":"Mental health chatbots","pd":"2022-10-01","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.5  Human computer interaction harm"],"t":"Mental health chatbots","s":"With human therapists in short supply, AI chatbots are trying to plug the gap—but it’s not clear how well they work. Teresa Berkowitz’s experiences with therapists had been hit or miss. ”Some good, some helpful, some just a waste of time and money,” she says. When some childhood trauma was reactivated six years ago, instead of connecting with a flesh-and-blood human, Berkowitz—who’s in her fifties and lives in the US state of Maine—downloaded Youper, a mental health app with a chatbot therapist function powered by artificial intelligence. Once or twice a week Berkowitz does guided journaling using the Youper chatbot, during which the bot prompts her to spot and change negative thinking patterns as she writes down her thoughts.","u":"https://www.wired.com/story/mental-health-chatbots/","d":"2022-10-01","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2022-10-01","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2022-10-01","organization":"Not specified in report","aiSystem":"Mental health app with a chatbot therapist function powered by artificial intelligence","affectedGroup":"Individuals seeking mental health support","action":"Chatbot therapist prompts users to spot and change negative thinking patterns during guided journaling sessions","consequence":"Misleading therapeutic guidance resulting in ineffective treatment and frustration"}},{"i":"R3013","hd":"Machine learning reproducibility crisis","pd":"2022-08-11","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.3  Misinformation / information hazard harm"],"t":"Machine learning reproducibility crisis","s":"AI hype has researchers in fields from medicine to political science rushing to use techniques that they don’t always understand—causing a wave of spurious results. History shows civil wars to be among the messiest, most horrifying of human affairs. So Princeton professor Arvind Narayanan and his PhD student Sayash Kapoor got suspicious last year when they discovered a strand of political science research claiming to predict when a civil war will break out with more than 90 percent accuracy, thanks to artificial intelligence A series of papers described astonishing results from using machine learning , the technique beloved by tech giants that underpins modern AI.","u":"https://www.wired.com/story/machine-learning-reproducibility-crisis/","d":"2022-08-11","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2022-08-11","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2022-08-11","organization":"Princeton professor Arvind Narayanan and his PhD student Sayash Kapoor","aiSystem":"Artificial Intelligence (AI)","affectedGroup":"Researchers in fields from medicine to political science","action":"Used machine learning techniques to predict civil wars","consequence":"Spurious results and misleading predictions"}},{"i":"R3014","hd":"Amazon irobot roomba acquisition data privacy","pd":"2022-08-05","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.1  Privacy violation"],"t":"Amazon irobot roomba acquisition data privacy","s":"Why is the Roomba company worth $1.7 billion to Amazon? It’s not the dust, it’s the data. After decades of creating war machines and home cleaning appliances , iRobot agreed to be acquired by Amazon for $1.7 billion, according to a joint statement by the two companies. If the deal goes through, it would give Amazon access to yet another wellspring of personal data: interior maps of Roomba owners’ homes. iRobot got its start building robots for the US military , but 20 years ago added consumer vacuums to the mix. (It spun off the defense business altogether in 2016.) Those Roombas work in part by using sensors to map the homes they operate in.","u":"https://www.wired.com/story/amazon-irobot-roomba-acquisition-data-privacy/","d":"2022-08-05","e":"Acute","x":{"occurrenceStatus":"probable","publicationDate":"2022-08-05","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2022-08-05","organization":"iRobot","aiSystem":"Roomba's mapping technology","affectedGroup":"Roomba owners","action":"Used sensors to map Roomba owners' homes","consequence":"Gave Amazon access to personal data"}},{"i":"R3015","hd":"Cruises robot car outages","pd":"2022-07-08","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.6  Quality of service harm"],"t":"Cruises robot car outages","s":"In a series of incidents, the GM subsidiary lost contact with its autonomous vehicles, leaving them frozen in traffic and trapping human drivers. Around midnight on June 28, Calvin Hu was driving with his girlfriend near San Francisco’s Golden Gate Park when he pulled up at an intersection behind two white and orange autonomous Chevrolet Bolts operated by Cruise, a subsidiary of General Motors Another was stopped to his right in the adjacent lane. The light turned green but the cars, which operate in the city without drivers , didn’t move. When Hu prepared to reverse and go around the frozen vehicles, he says, he noticed that several more Cruise vehicles had stopped in the lanes behind him.","u":"https://www.wired.com/story/cruises-robot-car-outages/","d":"2022-07-08","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2022-07-08","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2022-06-28","organization":"General Motors and Cruise","aiSystem":"Autonomous Chevrolet Bolts operated by Cruise, a subsidiary of General Motors","affectedGroup":"Human drivers","action":"Autonomous vehicles failed to move when the light turned green","consequence":"Human drivers were trapped in traffic and had to reverse their vehicles"}},{"i":"R3016","hd":"Roe abortion sex worker policy","pd":"2022-06-29","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.2  Surveillance harm"],"t":"Roe abortion sex worker policy","s":"FOSTA/SESTA laws deplatformed sex workers and set the stage to overturn Roe v. Wade. Friday’s Supreme Court decision to overturn Roe v. Wade is one of the most devastating rulings to come out of Washington. It’s also the next step in a larger campaign to expand state surveillance and erode the right to privacy—a campaign that sex workers have been fighting for decades. It’s not a stretch to connect abortion to sex work; Justice Samuel Alito even writes in the majority opinion for Dobbs v. Jackson Women’s Health Organization that the right to terminate a pregnancy “could license fundamental rights to illicit drug use, prostitution, and the like.”","u":"https://www.wired.com/story/roe-abortion-sex-worker-policy/","d":"2022-06-29","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2022-06-29","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2022-06-29","organization":"Not specified in report","aiSystem":"Not specified in report","affectedGroup":"People who engage in sex work","action":"Expanded state surveillance and erosion of privacy rights","consequence":"Increased risk of surveillance and tracking"}},{"i":"R3018","hd":"Airfare prediction tools","pd":"2022-06-03","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.2  Allocative harm"],"t":"Airfare prediction tools","s":"The world's current weirdness has made it more difficult for tools like Kayak and Google Flights to guess the best time to buy a plane ticket. Flying has always been a pain: the endless security lines, the hip-checking other passengers to make sure there’s overhead room for your rolly bag, the squeezing into a seat, the ear-popping, the spotty internet, the boredom. But these days, the irritation begins much earlier, when passengers start to look for tickets. The average round-trip ticket price in the US was $408 this week, up $100 from the same time in 2019, according to the airfare sales app Hopper. Part of that is pent-up demand from people sick of their homes after a still-not-over pandemic Another is high fuel prices, spurred upward by the war in Ukraine.","u":"https://www.wired.com/story/airfare-prediction-tools/","d":"2022-06-03","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2022-06-03","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2022-06-03","organization":"Kayak and Google Flights","aiSystem":"Airfare prediction tools","affectedGroup":"Passengers","action":"Predicted flight prices","consequence":"Increased ticket prices"}},{"i":"R3020","hd":"NYPD spot boston dynamics robot dog","pd":"2022-04-15","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.2  Surveillance harm"],"t":"Nypd spot boston dynamics robot dog","s":"Plus: Google Maps enhances coverage within US national parks, SwiftKey with Bing Chat lands on iPhones, and we track the rise of the AI voice clones. Our old friend Spot the robot dog is joining the Big Apple's police force. New York City mayor Eric Adams announced that the New York Police Department will be acquiring some new semi-autonomous robotic canines in the coming weeks. The move comes almost exactly two years after the NYPD halted its first go at using a camera-carrying robot dog for surveillance, after a massive public outcry; citizens felt it was a dystopian overreach of police power. Now Adams, a former NYPD captain, is moving the program forward again.","u":"https://www.wired.com/story/nypd-spot-boston-dynamics-robot-dog/","d":"2022-04-15","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2022-04-15","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2022-04-15","organization":"New York Police Department","aiSystem":"semi-autonomous robotic canines","affectedGroup":"citizens","action":"used for surveillance","consequence":"felt it was a dystopian overreach of police power"}},{"i":"R3023","hd":"Hidden role facial recognition tech arrests","pd":"2022-03-07","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.2  Surveillance harm"],"t":"Hidden role facial recognition tech arrests","s":"The technology is spreading fast among police, and often wrong. But people charged with crimes are rarely told an algorithm came into play. Application Face recognition End User Government Sector Public safety Source Data Images Technology Machine vision In April 2018, Bronx public defender Kaitlin Jackson was assigned to represent a man accused of stealing a pair of socks from a TJ Maxx store. The man said he couldn’t have stolen the socks because at the time the theft occurred, he was at a hospital about three-quarters of a mile away, where his son was born about an hour later. Jackson couldn’t understand how police had identified and arrested her client months after the theft.","u":"https://www.wired.com/story/hidden-role-facial-recognition-tech-arrests/","d":"2022-03-07","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2022-03-07","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"April 2018","organization":"Police authorities","aiSystem":"Facial recognition technology","affectedGroup":"Individual accused of theft","action":"Used facial recognition to identify and arrest","consequence":"Wrongful detention"}},{"i":"R3026","hd":"Artificial emotional intelligence","pd":"2021-12-30","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.1  Privacy violation"],"t":"Artificial emotional intelligence","s":"Technology used to only deliver our messages. Now it wants to write them for us by understanding our emotions. In May 2021, Twitter, a platform notorious for abuse and hot-headedness, rolled out a “prompts” feature that suggests users think twice before sending a tweet. The following month, Facebook announced AI “conflict alerts” for groups, so that admins can take action where there may be “contentious or unhealthy conversations taking place.” Email and messaging smart-replies finish billions of sentences for us every day. Amazon’s Halo, launched in 2020, is a fitness band that monitors the tone of your voice. Wellness is no longer just the tracking of a heartbeat or the counting of steps, but the way we come across to those around us.","u":"https://www.wired.com/story/artificial-emotional-intelligence/","d":"2021-12-30","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2021-12-30","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2021-06","organization":"Facebook","aiSystem":"Emotionally intelligent AI assistant","affectedGroup":"Group administrators","action":"Deployed AI conflict alerts","consequence":"May lead to contentious or unhealthy conversations"}},{"i":"R3028","hd":"3 years maven uproar google warms pentagon","pd":"2021-11-20","k":"United States of America","p":"United States of America","b":["Deployment Context / Weapons"],"h":["5.2  Military decision support harm"],"t":"3 years maven uproar google warms pentagon","s":"The company has contracts to detect corrosion on Navy ships and help maintain Air Force jets. Now it wants to bid for a lucrative cloud contract. In 2018, thousands of Google employees protested a Pentagon contract dubbed Project Maven that used the company’s artificial intelligence technology to analyze drone surveillance footage. Google said it wouldn’t renew the contract and announced guiding principles for future AI projects that forbid work on weapons and surveillance projects “violating internationally accepted norms.” At the same time, Google made clear it would still seek defense contracts. “While we are not developing AI for use in weapons,” CEO Sundar Pichai wrote, “we will continue our work with governments and the military in many other areas.”","u":"https://www.wired.com/story/3-years-maven-uproar-google-warms-pentagon/","d":"2021-11-20","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2021-11-20","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2018","organization":"Google","aiSystem":"Google's artificial intelligence technology","affectedGroup":"Google employees","action":"Used AI to analyze drone surveillance footage","consequence":"Protests and ethical guidelines"}},{"i":"R3029","hd":"Amazon failed to protect your data investigation","pd":"2021-11-18","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.1  Privacy violation"],"t":"Amazon failed to protect your data investigation","s":"Voyeurs. Sabotaged accounts. Backdoor schemes. For years, the retail giant has handled your information less carefully than it handles your packages. On September 26, 2018, a row of tech executives filed into a marble- and wood-paneled hearing room and sat down behind a row of tabletop microphones and tiny water bottles. They had all been called to testify before the US Senate Commerce Committee on a dry subject—the safekeeping and privacy of customer data—that had recently been making large numbers of people mad as hell. Committee chair John Thune, of South Dakota, gaveled the hearing to order, then began listing events from the past year that had shown how an economy built on data can go luridly wrong.","u":"https://www.wired.com/story/amazon-failed-to-protect-your-data-investigation/","d":"2021-11-18","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2021-11-18","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2018-09-26","organization":"Amazon","aiSystem":"Not specified in report","affectedGroup":"Customers","action":"Failed to protect customer data","consequence":"Data mishandling leading to privacy issues"}},{"i":"R3030","hd":"Company tapped AI website landed court","pd":"2021-11-11","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.2  Allocative harm"],"t":"Company tapped ai website landed court","s":"Under pressure to make their sites accessible to visually impaired users, firms turn to software. But advocates say the tech isn't always up to the task. Last year, Anthony Murphy, a visually impaired man who lives in Erie, Pennsylvania, visited the website of eyewear retailer Eyebobs using screen reader software. Its synthesized voice attempted to read out the page’s content, as well as navigation buttons and menus. Eyebobs used artificial intelligence software from Israeli startup AccessiBe that promised to make its site easier for people with disabilities to use. But Murphy found it made it harder. AccessiBe says it can simplify the work of making websites accessible to people with impaired vision or other challenges by “replacing a costly, manual process with an automated, state-of-the-art AI technology.”","u":"https://www.wired.com/story/company-tapped-ai-website-landed-court/","d":"2021-11-11","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2021-11-11","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2021-11-11","organization":"Eyebobs (eyewear retailer)","aiSystem":"Artificial intelligence software from Israeli startup AccessiBe","affectedGroup":"Visually impaired users","action":"Used artificial intelligence software to make the website easier to navigate for people with disabilities","consequence":"Made it harder for a visually impaired user to navigate the website"}},{"i":"R3033","hd":"NYPD secret fund surveillance tools","pd":"2021-08-10","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.2  Surveillance harm"],"t":"Nypd secret fund surveillance tools","s":"Documents reveal that police bought facial-recognition software, vans equipped with x-ray machines, and “stingray” cell site simulators—with no public oversight. New York City police bought a range of surveillance tools—including facial-recognition software, predictive policing software, vans equipped with x-ray machines to detect weapons, and “stingray” cell site simulators—with no public oversight, according to documents released Tuesday. In all, the documents show that the NYPD spent at least $159 million since 2007 through a little-known “Special Expenses Fund” that did not require approval by the city council or other municipal officials.","u":"https://www.wired.com/story/nypd-secret-fund-surveillance-tools/","d":"2021-08-10","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2021-08-10","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2021-08-10","organization":"New York City Police Department (NYPD)","aiSystem":"Facial recognition software, predictive policing software, x-ray vans, stingray cell site simulators","affectedGroup":"General public","action":"Bought and deployed surveillance tools without public oversight","consequence":"Exposure to invasive surveillance technologies"}},{"i":"R3034","hd":"Algorithm predicts deadly infections often flawed","pd":"2021-06-21","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.7  Physical safety harm"],"t":"Algorithm predicts deadly infections often flawed","s":"A study found that a system used to identify cases of sepsis missed most instances and frequently issued false alarms. A complication of infection known as sepsis is the number one killer in US hospitals. So it’s not surprising that more than 100 health systems use an early warning system offered by Epic Systems, the dominant provider of US electronic health records. The system throws up alerts based on a proprietary formula tirelessly watching for signs of the condition in a patient’s test results. But a new study using data from nearly 30,000 patients in University of Michigan hospitals suggests Epic’s system performs poorly.","u":"https://www.wired.com/story/algorithm-predicts-deadly-infections-often-flawed/","d":"2021-06-21","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2021-06-21","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2021-06-21","organization":"Epic Systems","aiSystem":"Epic Systems' early warning system","affectedGroup":"Patients in University of Michigan hospitals","action":"issued false alarms","consequence":"missed most instances of sepsis and caused false alarms"}},{"i":"R3037","hd":"Opinion new york citys surveillance battle offers national lessons","pd":"2021-02-12","k":"United States of America","p":"United States of America","b":["Data"],"h":["4.2  Surveillance harm"],"t":"Opinion new york citys surveillance battle offers national lessons","s":"A lack of police transparency highlights how citizens need to remain vigilant to take back control over their privacy. In January, when New York’s Public Oversight of Surveillance Technology Act went into effect, the City of New York Police Department was suddenly forced to detail the tools it had long kept from public view. But instead of giving New Yorkers transparency, the NYPD gave error-filled, boilerplate statements that hide almost everything of value. Almost none of the policies list specific vendors, surveillance tool models, or information-sharing practices. The department’s facial recognition policy says it can share data “pursuant to on-going criminal investigations, civil litigation, and disciplinary proceedings,” a standard so broad it’s largely meaningless.","u":"https://www.wired.com/story/opinion-new-york-citys-surveillance-battle-offers-national-lessons/","d":"2021-02-12","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2021-02-12","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"January","organization":"New York City Police Department","aiSystem":"Facial recognition technology","affectedGroup":"Citizens","action":"Provided vague and incomplete policy statements","consequence":"Failed to provide transparency and detailed information"}},{"i":"R3040","hd":"Rent robot worker less paying human","pd":"2021-01-22","k":"United States of America","p":"United States of America","b":["Labor"],"h":["3.3  Employment displacement / quality harm"],"t":"Rent robot worker less paying human","s":"Automation is reaching more companies, imperiling some jobs and changing the nature of others. Polar Manufacturing has been making metal hinges, locks, and brackets in south Chicago for more than 100 years. Some of the company’s metal presses—hulking great machines that loom over a worker—date from the 1950s. Last year, to meet rising demand amid a shortage of workers, Polar hired its first robot employee. The robot arm performs a simple, repetitive job: lifting a piece of metal into a press, which then bends the metal into a new shape. And like a person, the robot worker gets paid for the hours it works. Jose Figueroa, who manages Polar’s production line, says the robot, which is leased from a company called Formic, costs the equivalent of $8 per hour, compared with a minimum wage of $15 per hour for a human employee.","u":"https://www.wired.com/story/rent-robot-worker-less-paying-human/","d":"2021-01-22","e":"Chronic","x":{"occurrenceStatus":"occurred","publicationDate":"2021-01-22","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2021-01-22","organization":"Polar Manufacturing","aiSystem":"Not specified in report","affectedGroup":"Human employees","action":"Robot arm performs a simple, repetitive job of lifting metal into a press","consequence":"Robot worker gets paid less than a human employee"}},{"i":"R3041","hd":"Job screening service halts facial analysis applicants","pd":"2021-01-12","k":"United States of America","p":"United States of America","b":["Compute / Model Behavior"],"h":["1.2  Allocative harm"],"t":"Job screening service halts facial analysis applicants","s":"But it’s still using intonation and behavior to assist with hiring decisions. Job hunters may now need to impress not just prospective bosses but artificial intelligence algorithms too—as employers screen candidates by having them answer interview questions on a video that is then assessed by a machine. HireVue, a leading provider of software for vetting job candidates based on an algorithmic assessment, said Tuesday it is killing off a controversial feature of its software: analyzing a person’s facial expressions in a video to discern certain characteristics. Job seekers screened by HireVue sit in front of a webcam and answer questions.","u":"https://www.wired.com/story/job-screening-service-halts-facial-analysis-applicants/","d":"2021-01-12","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2021-01-12","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2021-01-12","organization":"HireVue","aiSystem":"HireVue, a leading provider of software for vetting job candidates based on an algorithmic assessment","affectedGroup":"Job applicants","action":"analyzing a person’s facial expressions in a video to discern certain characteristics","consequence":"killing off a controversial feature of its software"}},{"i":"R1009","hd":"Fake news AI avatars synthesia","pd":"2024-10-17","k":"Venezuela","p":"Venezuela","b":["Compute / Model Behavior"],"h":["1.3  Misinformation / information hazard harm"],"t":"Fake news ai avatars synthesia","s":"A character actor whose face you may have seen in some movies or shows had suddenly found himself out of work during the pandemic. To make a few bucks, he took on a gig that sounded a little iffy but hey, he needed the money. He sold his likeness to an AI company. The company […]. The company promised his likeness would not be used for anything nefarious. Now his face is being used in propaganda churned out by dictatorships. He’s not the only one. Dan Dewhirst is that actor. He had a small role in the Alien prequel Prometheus and was in the short-lived Netflix series The Dark Crystal: Age of Resistance During the pandemic, he was approached by a London-based AI startup called Synthesia.","u":"https://www.vice.com/en/article/fake-news-ai-avatars-synthesia/","d":"2024-10-17","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2024-10-17","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2024-10-17","organization":"London-based AI startup Synthesia","aiSystem":"Synthesia AI","affectedGroup":"character actor Dan Dewhirst","action":"sold his likeness to Synthesia","consequence":"his likeness used in propaganda by dictatorships"}},{"i":"R2082","hd":"US military anthropic AI model claude venezuela raid","pd":"2026-02-14","k":"Venezuela","p":"Venezuela","b":["Deployment Context / Weapons"],"h":["5.2  Military decision support harm"],"t":"Us military anthropic ai model claude venezuela raid","s":"Wall Street Journal says Claude used in operation via Anthropic’s partnership with Palantir Technologies. Claude, the AI model developed by Anthropic, was used by the US military during its operation to kidnap Nicolás Maduro from Venezuela, the Wall Street Journal revealed on Saturday, a high-profile example of how the US defence department is using artificial intelligence in its operations. The US raid on Venezuela involved bombing across the capital, Caracas, and the killing of 83 people, according to Venezuela’s defence ministry. Anthropic’s terms of use prohibit the use of Claude for violent ends, for the development of weapons or for conducting surveillance.","u":"https://www.theguardian.com/technology/2026/feb/14/us-military-anthropic-ai-model-claude-venezuela-raid","d":"2026-02-14","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2026-02-14","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2026-02-14","organization":"US military, US defence department","aiSystem":"Claude, the AI model developed by Anthropic","affectedGroup":"Nicolás Maduro","action":"Kidnapped Nicolás Maduro","consequence":"Exposure to violence and death"}},{"i":"R1509","hd":"Vietnam police catch ring using biometric face spoof to launder 39m","pd":"2025-06-02","k":"Vietnam","p":"Vietnam","b":["Compute / Model Behavior"],"h":["1.4  Malicious use harm"],"t":"Vietnam police catch ring using biometric face spoof to launder 39m","s":"Vietnam is adapting its rules for online account security as the country leans into digital transformation, but fraudsters are also innovating. Vietnam is adapting its rules for online account security as the country leans into digital transformation for government and business, but fraudsters are also innovating with fresh techniques. Police in Vietnam have arrested a 14-member gang for allegedly laundering VND 1 trillion ($38.4 million) using generative AI to defeat biometric security measures at banks, according to VN Express The gang, led by 46-year-old Pham Hong Chuyen from Hanoi, are under investigation for organizing illegal gambling from their bases in Hanoi and Ninh Binh province, according to Ninh Binh police, and are being questioned for money laundering.","u":"https://www.biometricupdate.com/202506/vietnam-police-catch-ring-using-biometric-face-spoof-to-launder-39m","d":"2025-06-02","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2025-06-02","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2025-06-02","organization":"Police in Vietnam","aiSystem":"Generative AI","affectedGroup":"Fraudsters","action":"Used generative AI to defeat biometric security measures","consequence":"Laundered VND 1 trillion ($38.4 million)"}},{"i":"R1600","hd":"Cybercriminals use malware to obtain face biometrics break into banking apps","pd":"2024-02-16","k":"Vietnam","p":"Vietnam","b":["Compute / Model Behavior"],"h":["1.4  Malicious use harm"],"t":"Cybercriminals use malware to obtain face biometrics break into banking apps","s":"Chinese cybercrime group GoldFactory is creating malware to attack Android and iOS that steals face biometrics and uses them to break into bank accounts of the victim, according to The Register The group started releasing trojanized smartphone apps in June 2023. The first version, GoldDigger, focused on getting banking credentials. The latest version, GoldPickaxe or GoldPickaxe.iOS for Android a. nd iOS, first appeared in October of that same year. It captures data used for identity verification, including face biometrics. Bleeping Computer says that Group-IB , a team of researchers investigating the attacks, believes cybercriminals harvest biometric data that users provide for verification in the apps, then use it to log into accounts on legitimate banking apps in Vietnam and Thailand.","u":"https://www.biometricupdate.com/202402/cybercriminals-use-malware-to-obtain-face-biometrics-break-into-banking-apps","d":"2024-02-16","e":"Acute","x":{"occurrenceStatus":"occurred","publicationDate":"2024-02-16","sourceLanguage":"en","dateBasis":"publication date","extractedEventDate":"2023-10","organization":"Cybercrime group GoldFactory","aiSystem":"Malware","affectedGroup":"Bank account holders in Vietnam and Thailand","action":"Steals face biometrics and uses them to gain unauthorized access to bank accounts","consequence":"Exposes victims' personal information and financial records, leading to potential financial loss"}}]);
